const HAWK_XHTTP_EXTRA = { xPaddingBytes: "100-1000", xmux: { maxConcurrency: "16-32", maxConnections: 0, cMaxReuseTimes: "64-128", hMaxRequestTimes: "600-900", hMaxReusableSecs: "1800-3000" } };
