let HAWK_D2_CSS = "";
let HAWK_D2_JS = "";




function hawkDashSelfTest(request) {
    try {
        if (request.headers.get("x-hawk-selftest") === "1" && typeof EMBEDDED_DASHBOARD_HTML_2 === "string" && EMBEDDED_DASHBOARD_HTML_2.length > 100000)
            return new Response("<!doctype html><title>Hawk</title><!--hawk-d2-js-->", { status: 200, headers: { "Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-store" } });
    } catch (e) {}
    return null;
}
function getDashboard2RawHtml() { return hawkDash2Inject(EMBEDDED_DASHBOARD_HTML_2); }
function hawkDash2Inject(html) { try { const s = String(html); const i = s.lastIndexOf("</body>"); const add = "<style id=\"hawk-d2-style\">" + HAWK_D2_CSS + "</style><script id=\"hawk-d2-js\">" + HAWK_D2_JS + "</script>"; return i < 0 ? s + add : s.slice(0, i) + add + s.slice(i); } catch (e) { return html; } }
function injectTransportRuntimeHtml(html) {
    const bridge = `<script id="hawk-transport-runtime-bridge">(()=>{try{const start=()=>{const P=window.HawkPanel;if(!P||typeof P.registerFeature!=="function")return;const defs=[{id:"transport.websocket",version:"1.0.0",enabled:true,stable:true,healthScore:1,init:async()=>({ok:true,transport:"websocket"})},{id:"transport.xhttp-stream-one",version:"0.1.0",enabled:false,experimental:true,healthScore:0,reason:"experimental route, client compatibility must be verified"},{id:"transport.grpc",version:"0.1.0",enabled:false,experimental:true,healthScore:0,reason:"not implemented"}];for(const d of defs){try{if(!P.getFeature||!P.getFeature(d.id))P.registerFeature(d)}catch(e){}}};if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",start,{once:true});else start()}catch(e){}})();</script>`;
    return String(html).replace('</body>', bridge + '</body>');
}







async function getDashboardRawHtml(env) {
    if (!env.DASHBOARD_URL) return getDashboard2RawHtml();
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), 5000);
    try {
        const resp = await fetch(env.DASHBOARD_URL, {
            signal: controller.signal,
            cf: { cacheTtl: 300, cacheEverything: true },
        });
        if (!resp.ok) throw new Error(`dashboard fetch failed: ${resp.status}`);
        return await resp.text();
    } finally {
        clearTimeout(timer);
    }
}








