const MB = 1048576;
const DGOV_BASE = 40 * MB, DGOV_FLOOR = 16 * MB, DGOV_CEIL = 64 * MB, DGOV_MIN = 128 * 1024, DGOV_MAX = 8 * MB;
const DGOV = { backlog: 0, peak: 0, throttled: 0, waitMs: 0, \u0074unnels: 0, since: Date.now(), isoCap: DGOV_BASE, tickAt: 0, changedAt: Date.now(),
    calmSince: Date.now(), pressSince: 0, lastEvict: 0, evicted: 0, fastReject: 0, bulkWaits: 0, fairWaits: 0, crashAt: 0, heal: [], set: new Set(), ub: new Map(), ut: new Map() };
function dgovOn() { return !(sysConfig && sysConfig.downGov === false); }
function dgovNote(t) { DGOV.heal.push({ at: Date.now(), t }); if (DGOV.heal.length > 8) DGOV.heal.shift(); }
function dgovTunCap() { return Math.max(2 * MB, Math.min(DGOV_MAX, Math.round(DGOV.isoCap / 10))); }
function dgovUsers() { return Math.max(1, DGOV.ut.size); }
function dgovUserCap() { return Math.max(6 * MB, Math.round((DGOV.isoCap * 1.5) / dgovUsers())); }
function dgovMapAdd(m, k, d) { if (!k) return; const v = (m.get(k) || 0) + d; if (v <= 0.5) m.delete(k); else m.set(k, v); }
function dgovNew(deliveryRate) {
    const dr = Number(deliveryRate) || 0;
    const seed = dr > 0 ? Math.min(DGOV_MAX, Math.max(DGOV_MIN * 2, dr * 4)) : 512 * 1024;
    DGOV.\u0074unnels++;
    const T = { est: 0, rate: seed, seed, t: Date.now(), born: Date.now(), bytes: 0, u: null, uk: null, done: false };
    DGOV.set.add(T);
    return T;
}
function dgovBind(T, u) { if (!T || T.uk || !u) return; T.uk = String(u); dgovMapAdd(DGOV.ut, T.uk, 1); }
function dgovIsBulk(T, now) { return T.bytes > 16 * MB || (T.bytes > 4 * MB && now - T.born > 20000); }
function dgovLag() { try { return Math.max(GOV.lag || 0, Date.now() - AUTO.lagAt < 15000 ? AUTO.lagPk : 0); } catch (e) { return 0; } }
function dgovTick(now) {
    if (now - DGOV.tickAt < 2000) return; DGOV.tickAt = now;
    const load = DGOV.backlog / DGOV.isoCap, lag = dgovLag();
    if (load >= 0.9) { if (!DGOV.pressSince) DGOV.pressSince = now; } else DGOV.pressSince = 0;
    if (load < 0.3 && lag < 150) { if (!DGOV.calmSince) DGOV.calmSince = now; } else DGOV.calmSince = 0;
    if (lag >= 800 && now - DGOV.changedAt > 10000 && DGOV.isoCap > DGOV_FLOOR) {
        DGOV.isoCap = Math.max(DGOV_FLOOR, Math.round(DGOV.isoCap * 0.7)); DGOV.changedAt = now;
        dgovNote("CPU تحت فشار (lag " + Math.round(lag) + "ms)؛ سقف صف شد " + Math.round(DGOV.isoCap / MB) + "MB");
        return;
    }
    const ceil = now - DGOV.crashAt < 3600000 ? DGOV_BASE : DGOV_CEIL;
    if (DGOV.calmSince && now - DGOV.calmSince > 120000 && now - DGOV.changedAt > 120000 && DGOV.isoCap < ceil) {
        DGOV.isoCap = Math.min(ceil, DGOV.isoCap + 4 * MB); DGOV.changedAt = now;
        dgovNote("آرومه؛ سقف صف رفت بالا: " + Math.round(DGOV.isoCap / MB) + "MB");
    }
}

function dgovHealAfterCrash(blMB, capMB) {
    const now = Date.now(); DGOV.crashAt = now;
    const n = Math.max(DGOV_FLOOR, Math.min(DGOV.isoCap, Math.round(DGOV_BASE * 0.6)));
    if (n < DGOV.isoCap) { DGOV.isoCap = n; DGOV.changedAt = now; }
    dgovNote("Worker قبلی با صف " + blMB + "/" + capMB + "MB افتاد؛ سقف صف شد " + Math.round(DGOV.isoCap / MB) + "MB");
}
function dgovDrain(T) {
    const now = Date.now(), dt = now - T.t; if (dt <= 0) { dgovTick(now); return; } T.t = now;
    const d = Math.min(T.est, (T.rate * dt) / 1000); T.est -= d; DGOV.backlog = Math.max(0, DGOV.backlog - d); dgovMapAdd(DGOV.ub, T.uk, -d);
    const load = DGOV.backlog / DGOV.isoCap;
    if (load < 0.25) T.rate = Math.min(DGOV_MAX, T.rate * (1 + Math.min(1, dt / 1000) * 0.4));
    else if (load > 0.5) T.rate = Math.max(DGOV_MIN, Math.max(T.seed * 0.5, T.rate * (1 - Math.min(1, dt / 1000) * 0.3)));
    dgovTick(now);
}
function dgovHog() { let best = null; for (const x of DGOV.set) if (!x.done && (!best || x.est > best.est)) best = x; return best; }
function dgovRejectNew() { return dgovOn() && DGOV.backlog > DGOV.isoCap * 0.95; }

async function dgovBefore(T, isClosed) {
    if (!T || !dgovOn()) return "";
    dgovDrain(T);
    let n = 0;
    for (;;) {
        if (isClosed() || n >= 40) return "";
        const now = Date.now(), bulk = dgovIsBulk(T, now), load = DGOV.backlog / DGOV.isoCap;
        if (DGOV.pressSince && now - DGOV.pressSince > 12000 && now - DGOV.lastEvict > 5000 && T.est > 512 * 1024 && !T.chat && dgovHog() === T) { 
            DGOV.lastEvict = now; DGOV.evicted++; DGOV.pressSince = now;
            dgovNote("صف " + Math.round(load * 100) + "% پر بود؛ پرمصرف‌ترین تونل (" + (Math.round(T.est / 104857.6) / 10) + "MB توی صف) بسته شد تا بقیه زنده بمونن");
            return "evict";
        }
        const tc = bulk && load > 0.5 ? dgovTunCap() / 2 : dgovTunCap();
        const overT = T.est > tc;
        const overU = DGOV.ut.size >= 2 && T.uk && (DGOV.ub.get(T.uk) || 0) > dgovUserCap();
        const overI = DGOV.backlog > DGOV.isoCap * (bulk ? 1 : 1.15);
        if (!overT && !overU && !overI) return "";
        if (!n) { DGOV.throttled++; if (bulk && !overT) DGOV.bulkWaits++; if (overU) DGOV.fairWaits++; }
        const over = Math.max(T.est - tc * 0.75, (DGOV.backlog - DGOV.isoCap * 0.75) / Math.max(1, DGOV.\u0074unnels), 16384);
        const ms = Math.max(25, Math.min(1500, Math.ceil((over / T.rate) * 1000)));
        DGOV.waitMs += ms; n++;
        await new Promise((r) => setTimeout(r, ms));
        dgovDrain(T);
    }
}
function dgovAfter(T, len) {
    if (!T || !dgovOn()) return;
    T.est += len; T.bytes += len; DGOV.backlog += len; dgovMapAdd(DGOV.ub, T.uk, len);
    if (DGOV.backlog > DGOV.peak) DGOV.peak = DGOV.backlog;
}
function dgovEnd(T) {
    if (!T || T.done) return; T.done = true; DGOV.set.delete(T);
    DGOV.backlog = Math.max(0, DGOV.backlog - T.est); dgovMapAdd(DGOV.ub, T.uk, -T.est); T.est = 0;
    if (T.uk) dgovMapAdd(DGOV.ut, T.uk, -1);
    DGOV.\u0074unnels = Math.max(0, DGOV.\u0074unnels - 1);
}
function dgovUserName(id) { try { const k = String(id).replace(/-/g, "").toLowerCase(); const u = (sysConfig.users || []).find((x) => x && x.id && String(x.id).replace(/-/g, "").toLowerCase() === k); return u ? String(u.name || "") : ""; } catch (e) { return ""; } }
function dgovTop() { let k = "", v = 0; for (const [a, b] of DGOV.ub) if (b > v) { k = a; v = b; } return k ? { name: dgovUserName(k) || k.slice(0, 8), mb: Math.round(v / 104857.6) / 10 } : null; }
function dgovView() {
    const top = dgovTop();
    return { on: dgovOn(), backlogMB: Math.round(DGOV.backlog / 104857.6) / 10, peakMB: Math.round(DGOV.peak / 104857.6) / 10, throttled: DGOV.throttled,
        waitSec: Math.round(DGOV.waitMs / 1000), \u0074unnels: DGOV.\u0074unnels, capMB: Math.round(DGOV.isoCap / MB), baseMB: DGOV_BASE / MB, \u0074unnelCapMB: Math.round(dgovTunCap() / 104857.6) / 10,
        users: DGOV.ut.size, userCapMB: Math.round(dgovUserCap() / MB), evicted: DGOV.evicted, fastReject: DGOV.fastReject, bulkWaits: DGOV.bulkWaits, fairWaits: DGOV.fairWaits,
        top, heal: DGOV.heal.slice().reverse() };
}

async function hawkBusyView() {
    const now = Date.now(); let hot = 0, busy = 0;
    const lv = (bl, cap, lag) => (cap > 0 && bl >= cap * 0.85) || lag >= 800 ? 2 : (cap > 0 && bl >= cap * 0.6) || lag >= 400 ? 1 : 0;
    const me = lv(DGOV.backlog / MB, DGOV.isoCap / MB, dgovLag()); if (me === 2) hot++; else if (me === 1) busy++;
    try { const t = await edgeCacheGetText(ISO_HB_EDGE); const m = t ? JSON.parse(t) || {} : {};
        for (const [id, v] of Object.entries(m)) { if (id === isoId() || !Array.isArray(v) || now - v[0] > 60000) continue; const l = lv(Number(v[3]) / 10 || 0, Number(v[4]) || 0, Number(v[2]) || 0); if (l === 2) hot++; else if (l === 1) busy++; } } catch (e) {}
    let protect = false; try { protect = hawkProtectOn(); } catch (e) {}
    const level = protect || hot ? "hot" : busy ? "busy" : "ok";
    return { level, protect };
}

function sendDownstreamJittered(webSocket, chunk, allowJitter = true) {
    const len = chunk.byteLength || 0;
    if (allowJitter && len > 4096 && typeof chunk.subarray === "function") {
        try {
            const splitAt = 512 + Math.floor(Math.random() * (len - 1024));
            webSocket.send(chunk.subarray(0, splitAt));
            webSocket.send(chunk.subarray(splitAt));
            return;
        } catch (e) {
            
        }
    }
    webSocket.send(chunk);
}









function sampleArray(arr, n) {
    if (arr.length <= n) return arr;
    const a = arr.slice();
    const cap = Math.min(n, a.length);
    for (let i = 0; i < cap; i++) {
        const j = i + Math.floor(Math.random() * (a.length - i));
        [a[i], a[j]] = [a[j], a[i]];
    }
    return a.slice(0, cap);
}










const relayLatencyMs = new Map();
function noteRelayLatency(host, ms) {
    if (!host || !(ms >= 0)) return;
    const prev = relayLatencyMs.get(host);
    relayLatencyMs.set(host, prev == null ? ms : prev * 0.7 + ms * 0.3);
    if (relayLatencyMs.size > 2000) relayLatencyMs.delete(relayLatencyMs.keys().next().value);
}
function relayLatencyFactor(host) {
    const ms = relayLatencyMs.get(host);
    if (ms == null) return 0.85;
    return 0.6 + 0.4 * (200 / (200 + ms));
}








const BRK = new Map();
const BRK_MAX = 3000;
const BRK_WINDOW_MS = 120000;
const BRK_TRIP = 3;
const BRK_BASE_MS = 60000;
const BRK_MAX_MS = 600000;
function _brkOpen(b, now) {
    b.open = Math.min(b.open + 1, 5);
    b.st = 1;
    b.until = now + Math.min(BRK_MAX_MS, BRK_BASE_MS * 2 ** (b.open - 1));
    b.fails.length = 0;
}
function brkOnResult(asn, host, ok, err = null) {
    if (!asn || !host || _hawkOff.has("breaker")) return;
    if (!ok) {
        const t = classifyRelayError(err);
        if (t === "dns" || t === "platform") return;
    }
    const k = asn + "|" + host;
    const now = Date.now();
    let b = BRK.get(k);
    if (!b) {
        if (ok) return;
        b = { st: 0, fails: [], open: 0, until: 0 };
        BRK.set(k, b);
        if (BRK.size > BRK_MAX) BRK.delete(BRK.keys().next().value);
    }
    if (ok) {
        b.fails.length = 0;
        if (b.st !== 0) { b.st = 0; b.open = Math.max(0, b.open - 1); }
        if (b.open === 0) BRK.delete(k);
        return;
    }
    if (b.st === 2 || (b.st === 1 && now >= b.until)) { _brkOpen(b, now); return; } 
    if (b.st === 1) return; 
    b.fails.push(now);
    while (b.fails.length && now - b.fails[0] > BRK_WINDOW_MS) b.fails.shift();
    if (b.fails.length >= BRK_TRIP) _brkOpen(b, now);
}
function brkWeight(asn, host) {
    if (!asn || _hawkOff.has("breaker")) return 1;
    const b = BRK.get(asn + "|" + host);
    if (!b || b.st === 0) return 1;
    if (b.st === 1 && Date.now() < b.until) return 0.05;
    b.st = 2; 
    return 0.5;
}
function brkOpenList(limit = 50) {
    const now = Date.now();
    const out = [];
    for (const [k, b] of BRK) {
        if (b.st === 0) continue;
        const i = k.indexOf("|");
        out.push({
            asn: k.slice(0, i),
            relay: k.slice(i + 1),
            state: b.st === 1 && now < b.until ? "OPEN" : "HALF_OPEN",
            trips: b.open,
            reopensInSec: b.st === 1 ? Math.max(0, Math.round((b.until - now) / 1000)) : 0,
        });
    }
    out.sort((a, b) => b.trips - a.trips);
    return out.slice(0, limit);
}
function brkStats() {
    let open = 0, half = 0;
    const now = Date.now();
    for (const b of BRK.values()) {
        if (b.st === 1 && now < b.until) open++;
        else if (b.st !== 0) half++;
    }
    return { routes: BRK.size, open, halfOpen: half };
}

function asnAdjustedRelayScore(baseScore, ip, clientAsn) {
    const f = relayLatencyFactor(ip) * relayHealthWeight(ip) * brkWeight(clientAsn, ip);
    const s = _asnAdjustedRelayScoreBase(baseScore, ip, clientAsn);
    return s > 0 ? s * f : f * 1e-6;
}
function _asnAdjustedRelayScoreBase(baseScore, ip, clientAsn) {
    if (!clientAsn) return baseScore;
    const stats = asnRelayStats.get(`${clientAsn}:${ip}`);
    if (!stats) return baseScore;
    const attempts = stats.successes + stats.fails;
    if (attempts < 3) return baseScore;
    const successRate = stats.successes / attempts;
    if (stats.avgBps > 0) {
        
        
        return stats.avgBps * 0.7 + baseScore * 0.3;
    }
    
    
    return baseScore * (0.5 + successRate);
}


const ADAPTIVE_FPS = ["chrome", "firefox", "safari", "edge", "ios", "android", "qq", "360"];
const FP_MIN_SAMPLES = 3;
const fpAsnStats = new Map();
let fpStatsLoadedAt = 0;
function fpStatKey(asn, fp) { return String(asn || "unknown") + "|" + fp; }
function fpRecord(asn, fp, ok, bytes=0) { if (!asn || !ADAPTIVE_FPS.includes(fp)) return; const k=fpStatKey(asn,fp); let r=fpAsnStats.get(k); if(!r||(r.t||0)<(fpResetAt.get(String(asn))||0)) r={ok:0,fail:0,bytes:0}; r.t=Date.now(); ok ? (r.ok++,r.bytes+=Math.max(0,Number(bytes)||0)) : r.fail++; fpAsnStats.set(k,r); if(fpAsnStats.size>512) fpAsnStats.delete(fpAsnStats.keys().next().value); }
function fpBestForAsn(asn) { if(!asn)return null; let best=null,score=-1; for(const fp of ADAPTIVE_FPS){const r=fpAsnStats.get(fpStatKey(asn,fp));if(!r||r.ok+r.fail<FP_MIN_SAMPLES)continue;const x=r.ok/Math.max(1,r.ok+r.fail),bps=r.ok?r.bytes/r.ok:0,s=x*100+Math.min(20,bps/500000);if(s>score){score=s;best=fp;}} return best; }

const fpResetAt = new Map(); 
function fpAsnOf(k) { const i = String(k).indexOf("|"); return i > 0 ? String(k).slice(0, i) : ""; }
function fpPurgeReset() { for (const [k, r] of fpAsnStats) { const ra = fpResetAt.get(fpAsnOf(k)) || 0; if (ra && (r.t || 0) < ra) fpAsnStats.delete(k); } }
function fpMergeResets(obj) { if (!obj || typeof obj !== "object") return; for (const a of Object.keys(obj)) { const t = Number(obj[a]) || 0; if (t > (fpResetAt.get(a) || 0)) fpResetAt.set(a, t); } fpPurgeReset(); }
function fpMergeRow(k, v) {
    if (!v || typeof v !== "object") return;
    if ((v.t || 0) < (fpResetAt.get(fpAsnOf(k)) || 0)) return;
    const cur = fpAsnStats.get(k);
    
    if (!cur) fpAsnStats.set(k, { ok: v.ok | 0, fail: v.fail | 0, bytes: Number(v.bytes) || 0, t: v.t || 0 });
    else fpAsnStats.set(k, { ok: Math.max(cur.ok, v.ok | 0), fail: Math.max(cur.fail, v.fail | 0), bytes: Math.max(cur.bytes, Number(v.bytes) || 0), t: Math.max(cur.t || 0, v.t || 0) });
}
function fpSyncFromEdge(){if(Date.now()-fpStatsLoadedAt<120000)return;fpStatsLoadedAt=Date.now();edgeCacheGetText("kv:fp_reset").then(r=>{try{if(r)fpMergeResets(JSON.parse(r))}catch(e){}return edgeCacheGetText("kv:fp_asn_stats");}).then(t=>{if(!t)return;try{for(const [k,v] of JSON.parse(t))fpMergeRow(k,v)}catch(e){}}).catch(()=>{});}
async function fpSyncFromEdgeNow(){fpStatsLoadedAt=Date.now();try{const r=await edgeCacheGetText("kv:fp_reset");if(r)fpMergeResets(JSON.parse(r));const t=await edgeCacheGetText("kv:fp_asn_stats");if(t)for(const [k,v] of JSON.parse(t))fpMergeRow(k,v);}catch(e){}}
let _fpLastPersist = 0;
function fpPersistToEdge(force = false){ const now = Date.now(); if (!force && now - _fpLastPersist < 60000) return; _fpLastPersist = now; edgeCachePutText("kv:fp_asn_stats",JSON.stringify(Array.from(fpAsnStats.entries()).slice(-512)),900,null).catch(()=>{});}

function effectiveUserFingerprint(profile, clientAsn=null) {
    const explicit=String(profile&&(profile.userFingerprint||profile.fingerprint)||"").toLowerCase();
    if(ADAPTIVE_FPS.includes(explicit)) return explicit;
    if (hawkSafeMode()) return "diverse";
    fpSyncFromEdge();
    return fpBestForAsn(clientAsn)||"diverse";
}
function resolveFingerprint(seed, profile=null, clientAsn=null) {
    const agent=profile?effectiveUserFingerprint(profile,clientAsn):(sysConfig.agent||"random");
    return agent==="diverse"?getDiverseFingerprint(seed):agent;
}

const safeBtoa = (str) => {
    try {
        const bytes = new TextEncoder().encode(str);
        let binary = "";
        for (let i = 0; i < bytes.byteLength; i++) {
            binary += String.fromCharCode(bytes[i]);
        }
        return btoa(binary);
    } catch (e) {
        return btoa(str);
    }
};

