const HAWK_MAX_USER_PORTS = 12;
const HAWK_MAX_GENERATED_CONFIGS = 2000;
function normalizeMaxConfigs(value) {
    const n = Number(value);
    if (!Number.isFinite(n) || n <= 0) return null;
    return Math.min(Math.floor(n), HAWK_MAX_GENERATED_CONFIGS);
}
const HAWK_ALLOWED_PROTOCOLS = new Set(["\x76less", "\x74rojan"]);
const HAWK_FRAGMENT_PRESETS = new Set(["off", "mci", "irancell", "rightel", "tci", "fiber"]);
function normalizeUserProtocols(value) {
    if (value == null || value === "" || value === "both") return ["\x76less", "\x74rojan"];
    const raw = Array.isArray(value) ? value : String(value).split(","), out = [];
    for (const item of raw) { const p = String(item).trim().toLowerCase(); if (HAWK_ALLOWED_PROTOCOLS.has(p) && !out.includes(p)) out.push(p); }
    return out.length ? out : ["\x76less", "\x74rojan"];
}
function normalizeUserPorts(value, fallback) {
    
    
    const toList = (v) => Array.isArray(v) ? v : (v == null ? [] : String(v).split(","));
    const raw = value == null || value === "" || (Array.isArray(value) && value.length === 0) ? toList(fallback) : toList(value), out = [];
    for (const item of raw) { const p = String(item).trim(), n = Number(p); if (/^\d{1,5}$/.test(p) && n >= 1 && n <= 65535 && !out.includes(p)) out.push(p); if (out.length >= HAWK_MAX_USER_PORTS) break; }
    return out.length ? out : ["443"];
}



function userPortsString(value, fallback) { return normalizeUserPorts(value, fallback).join(","); }
function normalizeUserFragment(value) { const p = String(value || "off").trim().toLowerCase(); return HAWK_FRAGMENT_PRESETS.has(p) ? p : "off"; }
function normalizeMuxMode(value) { const p = String(value || "off").trim().toLowerCase(); return ["off", "on", "auto"].includes(p) ? p : "off"; }
function normalizeMuxMap(value) {
    const raw = routeJson(value, {}), out = {};
    for (const [k, v] of Object.entries(raw || {}).slice(0, 32)) {
        const mode = normalizeMuxMode(v);
        if (/^[a-z0-9_-]{1,24}$/i.test(String(k))) out[String(k).toLowerCase()] = mode;
    }
    return JSON.stringify(out);
}
function normalizeMuxConfig(cfg) {
    cfg.muxMode = normalizeMuxMode(cfg.muxMode);
    cfg.muxConcurrency = Math.max(1, Math.min(32, Number(cfg.muxConcurrency) || 8));
    cfg.muxByOperator = normalizeMuxMap(cfg.muxByOperator);
    cfg.safeMode = cfg.safeMode === true || cfg.safeMode === "true";
    return cfg;
}

function normalizeNetworkProfile(value) {
    const p = String(value || "adaptive").trim().toLowerCase();
    return p === "strict" ? "strict" : "adaptive";
}
function hawkNetworkProfile() {
    return normalizeNetworkProfile(sysConfig && sysConfig.networkProfile);
}


const HawkRepositoryMetrics={reads:0,writes:0,memoryHits:0,edgeHits:0,d1Reads:0,d1Writes:0,staleReads:0,timeouts:0,errors:0,lastSource:"none",lastError:null,lastAt:0};
