const _relaySpeedBuf = new Map();   
const _usageBuf = new Map();        
const _directIpBuf = new Map();     
const _directDomainBuf = new Map(); 
const _asnDomainBuf = new Map();    
const _asnRelayBuf = new Map();     

let _lastStatsFlush = 0;
let _statsFlushPromise = null, _statsFlushAt = 0;
const STATS_FLUSH_INTERVAL_MS = 60000; 
const MAX_FLUSH_STATEMENTS = 120; 







const STATS_BUF_MAX_KEYS = 5000;
function _capStatsBuf(map) {
    while (map.size > STATS_BUF_MAX_KEYS) {
        const oldestKey = map.keys().next().value;
        if (oldestKey === undefined) break;
        map.delete(oldestKey);
    }
}
function _statsBufEntry(map, key) {
    let e = map.get(key);
    if (!e) {
        e = { successDelta: 0, failDelta: 0, bpsLatest: null };
        map.set(key, e);
        _capStatsBuf(map);
    }
    return e;
}

function bufferDirectIp(domain, ip, port) {
    if (!domain || !ip) return;
    const isNewKey = !_directIpBuf.has(domain);
    _directIpBuf.set(domain, { ip, port });
    if (isNewKey) _capStatsBuf(_directIpBuf);
}






const HAWK_GB_UNITS = 6000, HAWK_GB_BYTES = 1073741824;
function hawkUsageDay() { return new Date().toISOString().split("T")[0]; }
function hawkUsageUnits(b) { return Math.floor(((b || 0) * HAWK_GB_UNITS) / HAWK_GB_BYTES); }
function hawkUsageRoll(u, day) {
    const mon = day.slice(0, 7);
    if (u.month !== mon) { u.mB = 0; u.mU = 0; u.month = mon; u.reqs = 0; }
    if (u.lastDay !== day) { u.dB = 0; u.lastDay = day; u.dReqs = 0; }
}
const _usageUpBuf = new Map(); 
let _hawkUpColReady = false;
async function hawkUsageUpCol(env) {
    if (_hawkUpColReady || !env || !env.IOT_DB) return _hawkUpColReady;
    try {
        const f = await env.IOT_DB.prepare("SELECT value FROM kv_store WHERE key = ?").bind("usage_up_col_v1").first("value");
        if (!f) {
            try { await env.IOT_DB.prepare("ALTER TABLE usage_bytes ADD COLUMN month_up INTEGER DEFAULT 0").run(); } catch (e) { if (!/duplicate column/i.test(String(e && e.message))) throw e; }
            await env.IOT_DB.prepare("INSERT INTO kv_store (key, value) VALUES (?, ?) ON CONFLICT(key) DO UPDATE SET value = excluded.value").bind("usage_up_col_v1", "1").run();
        }
        _hawkUpColReady = true;
    } catch (e) {}
    return _hawkUpColReady;
}
function hawkUsageAddBytes(uuid, n, up = false) {
    if (!uuid || !(n > 0)) return;
    if (!sysUsageCache) sysUsageCache = { users: {} };
    if (!sysUsageCache.users) sysUsageCache.users = {};
    const day = hawkUsageDay();
    let u = sysUsageCache.users[uuid];
    if (!u) u = sysUsageCache.users[uuid] = { reqs: 0, dReqs: 0, lastDay: day, month: day.slice(0, 7), mB: 0, dB: 0 };
    hawkUsageRoll(u, day);
    u.mB = (u.mB || 0) + n; u.dB = (u.dB || 0) + n;
    if (up) { u.mU = (u.mU || 0) + n; _usageUpBuf.set(uuid, (_usageUpBuf.get(uuid) || 0) + n); }
    u.reqs = hawkUsageUnits(u.mB); u.dReqs = hawkUsageUnits(u.dB);
    const isNewKey = !_usageBuf.has(uuid);
    _usageBuf.set(uuid, (_usageBuf.get(uuid) || 0) + n);
    if (isNewKey) _capStatsBuf(_usageBuf);
}

function bufferRelaySuccess(host, bps) {
    if (!host) return;
    const e = _statsBufEntry(_relaySpeedBuf, host);
    e.successDelta++;
    e.bpsLatest = bps || 0;
}
function bufferRelayFailure(host) {
    if (!host) return;
    _statsBufEntry(_relaySpeedBuf, host).failDelta++;
}
function bufferDirectSuccess(domain) {
    if (!domain) return;
    _statsBufEntry(_directDomainBuf, domain).successDelta++;
}
function bufferDirectFailure(domain) {
    if (!domain) return;
    _statsBufEntry(_directDomainBuf, domain).failDelta++;
}
function bufferAsnDomainSuccess(asn, domain) {
    if (!asn || !domain) return;
    _statsBufEntry(_asnDomainBuf, `${asn}:${domain}`).successDelta++;
}
function bufferAsnDomainFailure(asn, domain) {
    if (!asn || !domain) return;
    _statsBufEntry(_asnDomainBuf, `${asn}:${domain}`).failDelta++;
}
function bufferAsnRelaySuccess(asn, ip, bps) {
    if (!asn || !ip) return;
    const e = _statsBufEntry(_asnRelayBuf, `${asn}:${ip}`);
    e.successDelta++;
    e.bpsLatest = bps || 0;
}
function bufferAsnRelayFailure(asn, ip) {
    if (!asn || !ip) return;
    _statsBufEntry(_asnRelayBuf, `${asn}:${ip}`).failDelta++;
}











const _cleanIpBuf = new Map();
const _cleanIpServedSeen = new Map(); 
const CLEANIP_SERVE_DEDUPE_MS = 6 * 3600 * 1000;
const CLEANIP_TRIAL_MS = 36 * 3600 * 1000;     
const CLEANIP_RETRY_MS = 7 * 24 * 3600 * 1000; 
const _cleanIpKeyMemo = new Map();
function cleanIpKey(ip) {
    const memo = _cleanIpKeyMemo.get(ip);
    if (memo !== undefined) return memo;
    const key = _cleanIpKeyRaw(ip);
    if (_cleanIpKeyMemo.size > 20000) _cleanIpKeyMemo.clear();
    _cleanIpKeyMemo.set(ip, key);
    return key;
}
function _cleanIpKeyRaw(ip) {
    
    let h = 0x811c9dc5;
    const str = String(ip || "").trim().toLowerCase();
    for (let i = 0; i < str.length; i++) {
        h ^= str.charCodeAt(i);
        h = Math.imul(h, 0x01000193) >>> 0;
    }
    return h.toString(36);
}
function _cleanIpEntry(asn, key) {
    const k = `${asn}|${key}`;
    let e = _cleanIpBuf.get(k);
    if (!e) {
        e = { ok: 0, bad: 0, bps: null, served: false };
        _cleanIpBuf.set(k, e);
        _capStatsBuf(_cleanIpBuf);
    }
    return e;
}
function bufferCleanIpOutcome(asn, key, ok, bps) {
    if (!asn || !key) return;
    const e = _cleanIpEntry(asn, key);
    if (ok) {
        e.ok++;
        if (bps) e.bps = bps;
    } else e.bad++;
}
function bufferCleanIpServed(asn, key) {
    if (!asn || !key) return;
    const k = `${asn}|${key}`;
    const now = Date.now();
    const seen = _cleanIpServedSeen.get(k);
    if (seen && now - seen < CLEANIP_SERVE_DEDUPE_MS) return;
    _cleanIpServedSeen.set(k, now);
    if (_cleanIpServedSeen.size > 20000) _cleanIpServedSeen.clear();
    _cleanIpEntry(asn, key).served = true;
}


const _cleanIpAsnCache = new Map(); 
const CLEANIP_ASN_CACHE_MS = 5 * 60 * 1000; 
let _cleanIpDeadGlobal = null;
let _cleanIpDeadGlobalTs = 0;
const CLEANIP_DEAD_CACHE_MS = 3 * 3600 * 1000;
async function loadCleanIpStatsForAsn(env, asn) {
    const cached = _cleanIpAsnCache.get(asn);
    if (cached && Date.now() - cached.ts < CLEANIP_ASN_CACHE_MS) return cached;
    let rows = null;
    const edge = await edgeCacheGetText(`kv:cleanip:${asn}`);
    if (edge !== null) {
        try { rows = JSON.parse(edge); } catch (e) {}
    }
    if (!rows) {
        await d1Init(env);
        const { results } = await Promise.race([
            env.IOT_DB.prepare(
                "SELECT k, ok, bad, avg_bps, last_ok, first_served, last_served FROM asn_cleanip_stats WHERE asn = ? LIMIT 5000",
            ).bind(String(asn)).all(),
            new Promise((_, reject) => setTimeout(() => reject(new Error("d1 timeout")), 4000)),
        ]);
        rows = (results || []).map((r) => [r.k, r.ok || 0, r.bad || 0, r.avg_bps || 0, r.last_ok || 0, r.first_served || 0, r.last_served || 0]);
        edgeCachePutText(`kv:cleanip:${asn}`, JSON.stringify(rows), 180, null);
    }
    const stats = new Map();
    const now = Date.now();
    let active = false;
    for (const r of rows) {
        stats.set(r[0], { ok: r[1], bad: r[2], bps: r[3], lastOk: r[4], firstServed: r[5], lastServed: r[6] });
        if (r[4] && now - r[4] < 24 * 3600 * 1000) active = true;
    }
    const out = { ts: Date.now(), stats, active };
    _cleanIpAsnCache.set(asn, out);
    if (_cleanIpAsnCache.size > 200) _cleanIpAsnCache.clear();
    return out;
}
async function loadCleanIpDeadGlobal(env) {
    if (_cleanIpDeadGlobal && Date.now() - _cleanIpDeadGlobalTs < CLEANIP_DEAD_CACHE_MS) return _cleanIpDeadGlobal;
    let keys = null;
    const edge = await edgeCacheGetText("kv:cleanip_dead");
    if (edge !== null) {
        try { keys = JSON.parse(edge); } catch (e) {}
    }
    if (!keys) {
        await d1Init(env);
        const now = Date.now();
        
        
        
        
        
        const { results } = await Promise.race([
            env.IOT_DB.prepare(
                `SELECT k FROM asn_cleanip_stats
                 WHERE asn IN (SELECT asn FROM asn_cleanip_stats WHERE last_ok > ?1 GROUP BY asn)
                   AND last_served > ?2
                 GROUP BY k
                 HAVING COUNT(*) >= 2
                    AND SUM(CASE WHEN ?3 - MAX(COALESCE(last_ok, 0), first_served) > ?4 THEN 1 ELSE 0 END) = COUNT(*)
                 LIMIT 5000`,
            ).bind(now - 24 * 3600 * 1000, now - CLEANIP_RETRY_MS, now, CLEANIP_TRIAL_MS).all(),
            new Promise((_, reject) => setTimeout(() => reject(new Error("d1 timeout")), 4000)),
        ]);
        keys = (results || []).map((r) => r.k);
        edgeCachePutText("kv:cleanip_dead", JSON.stringify(keys), 3600, null);
    }
    _cleanIpDeadGlobal = new Set(keys);
    _cleanIpDeadGlobalTs = Date.now();
    return _cleanIpDeadGlobal;
}



let _pendingSubRankCtx = null;
function takeSubRankCtx() {
    const c = _pendingSubRankCtx;
    _pendingSubRankCtx = null;
    return c;
}




let _pendingSubSlot = null;
function takeSubSlot() {
    const c = _pendingSubSlot;
    _pendingSubSlot = null;
    return c && Date.now() - c.t < 3000 ? c : null;
}
const HAWK_ISO_GROUPS = { n: 0, c: 0, cm: 0, f: 1, fc: 1, k: 1, kb: 1, kf: 1, ks: 1, kr: 1, e: 2, e2: 3, p: 4, x: 5, ef: 6 };
const HAWK_ISO_OF = 7, HAWK_ISO_MIN = 3;
function hawkIsoOn() { return !(sysConfig && sysConfig.subIsolate === false); }
function hawkIsoSlotFor(key, auto, url) {
    if (auto || !hawkIsoOn()) return null;
    const off = String((url && url.searchParams && url.searchParams.get("iso")) || "").toLowerCase();
    if (off === "0" || off === "off" || off === "false") return null;
    const g = HAWK_ISO_GROUPS[key];
    return g === undefined ? null : { slot: g, of: HAWK_ISO_OF };
}
function hawkIsoHash(str) { let h = 2166136261; for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 16777619) >>> 0; } return h >>> 0; }
function hawkIsoPick(list, sl) {
    if (!sl || !Array.isArray(list) || list.length <= HAWK_ISO_MIN) return list;
    const mine = list.filter((e) => hawkIsoHash(String(e)) % sl.of === sl.slot);
    if (mine.length >= HAWK_ISO_MIN) return mine;
    const have = new Set(mine);
    const extra = list.filter((e) => !have.has(e)).map((e) => [hawkIsoHash(String(e) + "#" + sl.slot), e]).sort((a, b) => a[0] - b[0]).map((x) => x[1]);
    const out = mine.slice();
    for (const e of extra) { if (out.length >= HAWK_ISO_MIN) break; out.push(e); }
    const idx = new Map(list.map((e, i) => [e, i]));
    return out.sort((a, b) => idx.get(a) - idx.get(b));
}
async function loadSubRankCtx(env, asn) {
    if (!env || !env.IOT_DB || !asn) return null;
    try {
        const [asnData, deadGlobal] = await Promise.all([
            loadCleanIpStatsForAsn(env, String(asn)),
            loadCleanIpDeadGlobal(env).catch(() => new Set()),
        ]);
        return { asn: String(asn), stats: asnData.stats, active: asnData.active, deadGlobal };
    } catch (e) {
        
        return { asn: String(asn), stats: new Map(), active: false, deadGlobal: new Set() };
    }
}













const CLEANIP_FAST_DEAD_MS = 6 * 3600 * 1000;
const CLEANIP_FAST_RETRY_MS = 3 * 24 * 3600 * 1000;
function cleanIpStrict() { return !_hawkOff.has("cleanstrict"); }
function cleanIpRetryMs() { return cleanIpStrict() ? CLEANIP_FAST_RETRY_MS : CLEANIP_RETRY_MS; }
function rankCleanIps(ips, needed, rank, unlimited = false) {
    const now = Date.now();
    const strict = cleanIpStrict();
    const deadMs = strict ? CLEANIP_FAST_DEAD_MS : CLEANIP_TRIAL_MS;
    const retryMs = cleanIpRetryMs();
    const local = (k) => _cleanIpBuf.get(`${rank.asn}|${k}`);
    let netLastOk = 0;
    if (strict) {
        for (const r of rank.stats.values()) if (r.lastOk > netLastOk) netLastOk = r.lastOk;
        for (const [bk, e] of _cleanIpBuf) if (e.ok > 0 && bk.startsWith(rank.asn + "|")) netLastOk = now;
    }
    const good = [], untested = [], weak = [], dead = [];
    for (const ip of ips) {
        const k = cleanIpKey(ip);
        if (rank.deadGlobal && rank.deadGlobal.has(k)) { dead.push(ip); continue; }
        let r = rank.stats.get(k);
        const lb = strict ? local(k) : null;
        if (lb && (lb.ok || lb.bad)) {
            r = r ? { ...r } : { ok: 0, bad: 0, bps: 0, lastOk: 0, firstServed: 0, lastServed: 0 };
            r.ok += lb.ok; r.bad += lb.bad;
            if (lb.ok > 0) { r.lastOk = now; if (lb.bps) r.bps = r.bps ? r.bps * 0.6 + lb.bps * 0.4 : lb.bps; }
        }
        if (!r) { untested.push(ip); continue; }
        const retrial = r.lastServed && now - r.lastServed > retryMs;
        const trialStart = retrial ? now : r.firstServed;
        if (strict) {
            if (retrial) { untested.push(ip); continue; }
            if (!(r.ok > 0)) {
                const usedSince = netLastOk > (trialStart || now);
                if (r.bad >= 2 || (usedSince && trialStart && now - trialStart > deadMs)) weak.push(ip);
                else untested.push(ip);
                continue;
            }
            const att = r.ok + r.bad;
            if (att >= 5 && r.ok / att < 0.35) { weak.push(ip); continue; }
            if (rank.active && now - Math.max(r.lastOk || 0, trialStart || now) > CLEANIP_TRIAL_MS) { weak.push(ip); continue; }
        } else {
            const deadHere = rank.active && now - Math.max(r.lastOk || 0, trialStart || now) > deadMs;
            if (deadHere) { weak.push(ip); continue; }
            if (!(r.ok > 0)) { untested.push(ip); continue; }
        }
        const reliability = (r.ok + 1) / (r.ok + r.bad + 2);
        const speed = 1 + Math.log10(1 + (r.bps || 0) / 1000);
        const fresh = r.lastOk && now - r.lastOk < 24 * 3600 * 1000 ? 1 : 0.7;
        good.push({ ip, score: reliability * speed * fresh, bps: r.bps || 0 });
    }
    good.sort((a, b) => b.score - a.score);
    let slow = [];
    if (strict && good.length >= 4) {
        const sp = good.map((g) => g.bps).filter((x) => x > 0).sort((a, b) => a - b);
        if (sp.length >= 4) {
            const median = sp[Math.floor(sp.length / 2)];
            const keep = good.filter((g) => !(g.bps > 0 && g.bps < median * 0.25));
            if (keep.length >= 3) { slow = good.filter((g) => !keep.includes(g)).map((g) => g.ip); good.length = 0; good.push(...keep); }
        }
    }
    const goodIps = good.map((g) => g.ip);
    let explore = 0;
    if (untested.length > 0 && goodIps.length > 0) {
        explore = strict ? Math.min(3, Math.max(1, Math.round(needed * 0.1))) : Math.max(1, Math.round(needed * 0.2));
    }
    
    
    if (strict && unlimited && goodIps.length >= 5) needed = Math.min(needed, goodIps.length + explore);
    const picked = [];
    const used = new Set();
    const take = (list, n) => {
        for (const ip of list) {
            if (picked.length >= needed || n <= 0) break;
            if (used.has(ip)) continue;
            used.add(ip); picked.push(ip); n--;
        }
    };
    take(goodIps, needed - explore);
    take(sampleArray(untested, explore), explore);
    take(goodIps, needed);
    take(slow, needed);
    take(strict ? sampleArray(untested, untested.length) : untested, needed);
    if (!strict || picked.length === 0) take(weak, needed);
    if (picked.length === 0) take(dead, needed);
    for (const ip of picked) bufferCleanIpServed(rank.asn, cleanIpKey(ip));
    return picked;
}
async function maybeFlushStatsBuffers(env, ctx) {
    if (!env || !env.IOT_DB) return;
    const now = Date.now();
    if (_statsFlushPromise && now - _statsFlushAt > 30000) _statsFlushPromise = null; 
    if (_statsFlushPromise) {
        if (ctx && typeof ctx.waitUntil === "function") {
            ctx.waitUntil(_statsFlushPromise.catch(() => {}));
        }
        return;
    }
    if (now - _lastStatsFlush < STATS_FLUSH_INTERVAL_MS) return;
    
    
    const _gov = govLevel();
    if (_gov >= 3 && now - _lastStatsFlush < STATS_FLUSH_INTERVAL_MS * 3) return;
    
    
    
    
    
    if (_gov >= 2) {
        
    } else if (ctx && typeof ctx.waitUntil === "function") {
        ctx.waitUntil(pruneStaleD1Rows(env).catch(() => {}));
    } else {
        pruneStaleD1Rows(env).catch(() => {});
    }
    if (
        _relaySpeedBuf.size === 0 &&
        _directDomainBuf.size === 0 &&
        _asnDomainBuf.size === 0 &&
        _asnRelayBuf.size === 0 &&
        _usageBuf.size === 0 &&
        _directIpBuf.size === 0 &&
        _cleanIpBuf.size === 0
    ) {
        _lastStatsFlush = now;
        return;
    }
    _statsFlushAt = now;
    _statsFlushPromise = _flushStatsBuffersNow(env).finally(() => {
        _statsFlushPromise = null;
    });
    if (ctx && typeof ctx.waitUntil === "function") {
        ctx.waitUntil(_statsFlushPromise.catch(() => {}));
    } else {
        _statsFlushPromise.catch(() => {});
    }
}

async function _flushStatsBuffersNow(env) {
    await d1Init(env);
    _lastStatsFlush = Date.now();
    
    
    const relaySnap = new Map(_relaySpeedBuf); _relaySpeedBuf.clear();
    const directSnap = new Map(_directDomainBuf); _directDomainBuf.clear();
    const asnDomainSnap = new Map(_asnDomainBuf); _asnDomainBuf.clear();
    const asnRelaySnap = new Map(_asnRelayBuf); _asnRelayBuf.clear();
    const usageSnap = new Map(_usageBuf); _usageBuf.clear();
    const directIpSnap = new Map(_directIpBuf); _directIpBuf.clear();
    const cleanIpSnap = new Map(_cleanIpBuf); _cleanIpBuf.clear();

    const now = Date.now();
    const statements = [];

    
    
    for (const [key, e] of cleanIpSnap) {
        const idx = key.indexOf("|");
        const asn = key.slice(0, idx), k = key.slice(idx + 1);
        statements.push(
            env.IOT_DB.prepare(
                `INSERT INTO asn_cleanip_stats (asn, k, ok, bad, avg_bps, last_ok, first_served, last_served, updated_at)
                 VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?8, ?8, ?8)
                 ON CONFLICT(asn, k) DO UPDATE SET
                     ok = ok + excluded.ok,
                     bad = bad + excluded.bad,
                     avg_bps = CASE WHEN excluded.avg_bps > 0 THEN (CASE WHEN avg_bps > 0 THEN avg_bps * 0.6 + excluded.avg_bps * 0.4 ELSE excluded.avg_bps END) ELSE avg_bps END,
                     last_ok = COALESCE(excluded.last_ok, last_ok),
                     first_served = CASE WHEN ?7 = 1 AND last_served < ?9 THEN ?8 ELSE first_served END,
                     last_served = CASE WHEN ?7 = 1 THEN ?8 ELSE last_served END,
                     updated_at = ?8`,
            ).bind(asn, k, e.ok, e.bad, e.bps || 0, e.ok > 0 ? now : null, e.served ? 1 : 0, now, now - cleanIpRetryMs()),
        );
    }

    for (const [host, e] of relaySnap) {
        if (e.bpsLatest != null) {
            statements.push(
                env.IOT_DB.prepare(
                    `INSERT INTO relay_speed (host, avg_bps, updated_at, success_count, fail_count)
                     VALUES (?, ?, ?, ?, ?)
                     ON CONFLICT(host) DO UPDATE SET
                         avg_bps = avg_bps * 0.6 + excluded.avg_bps * 0.4,
                         success_count = success_count + excluded.success_count,
                         fail_count = fail_count + excluded.fail_count,
                         updated_at = excluded.updated_at`,
                ).bind(host, e.bpsLatest, now, e.successDelta, e.failDelta),
            );
        } else {
            statements.push(
                env.IOT_DB.prepare(
                    `INSERT INTO relay_speed (host, avg_bps, updated_at, success_count, fail_count)
                     VALUES (?, 0, ?, ?, ?)
                     ON CONFLICT(host) DO UPDATE SET
                         success_count = success_count + excluded.success_count,
                         fail_count = fail_count + excluded.fail_count,
                         updated_at = excluded.updated_at`,
                ).bind(host, now, e.successDelta, e.failDelta),
            );
        }
    }
    for (const [domain, e] of directSnap) {
        statements.push(
            env.IOT_DB.prepare(
                `INSERT INTO direct_domain_stats (domain, success_count, fail_count, updated_at)
                 VALUES (?, ?, ?, ?)
                 ON CONFLICT(domain) DO UPDATE SET
                     success_count = success_count + excluded.success_count,
                     fail_count = fail_count + excluded.fail_count,
                     updated_at = excluded.updated_at`,
            ).bind(domain, e.successDelta, e.failDelta, now),
        );
    }
    for (const [key, e] of asnDomainSnap) {
        const idx = key.indexOf(":");
        const asn = key.slice(0, idx), domain = key.slice(idx + 1);
        statements.push(
            env.IOT_DB.prepare(
                `INSERT INTO asn_domain_stats (asn, domain, success_count, fail_count, updated_at)
                 VALUES (?, ?, ?, ?, ?)
                 ON CONFLICT(asn, domain) DO UPDATE SET
                     success_count = success_count + excluded.success_count,
                     fail_count = fail_count + excluded.fail_count,
                     updated_at = excluded.updated_at`,
            ).bind(asn, domain, e.successDelta, e.failDelta, now),
        );
    }
    for (const [key, e] of asnRelaySnap) {
        const idx = key.indexOf(":");
        const asn = key.slice(0, idx), ip = key.slice(idx + 1);
        if (e.bpsLatest != null) {
            statements.push(
                env.IOT_DB.prepare(
                    `INSERT INTO asn_relay_stats (asn, ip, success_count, fail_count, avg_bps, updated_at)
                     VALUES (?, ?, ?, ?, ?, ?)
                     ON CONFLICT(asn, ip) DO UPDATE SET
                         success_count = success_count + excluded.success_count,
                         fail_count = fail_count + excluded.fail_count,
                         avg_bps = avg_bps * 0.6 + excluded.avg_bps * 0.4,
                         updated_at = excluded.updated_at`,
                ).bind(asn, ip, e.successDelta, e.failDelta, e.bpsLatest, now),
            );
        } else {
            statements.push(
                env.IOT_DB.prepare(
                    `INSERT INTO asn_relay_stats (asn, ip, success_count, fail_count, avg_bps, updated_at)
                     VALUES (?, ?, ?, ?, 0, ?)
                     ON CONFLICT(asn, ip) DO UPDATE SET
                         success_count = success_count + excluded.success_count,
                         fail_count = fail_count + excluded.fail_count,
                         updated_at = excluded.updated_at`,
                ).bind(asn, ip, e.successDelta, e.failDelta, now),
            );
        }
    }

    for (const [domain, e] of directIpSnap) {
        statements.push(
            env.IOT_DB.prepare(
                `INSERT INTO direct_ip_history (domain, ip, port, updated_at)
                 VALUES (?, ?, ?, ?)
                 ON CONFLICT(domain) DO UPDATE SET
                     ip = excluded.ip,
                     port = excluded.port,
                     updated_at = excluded.updated_at`,
            ).bind(domain, e.ip, e.port, now),
        );
    }

    
    
    
    
    
    
    
    
    
    
    
    
    const today = new Date().toISOString().split("T")[0];
    const month = today.slice(0, 7);
    const upSnap = new Map(_usageUpBuf); _usageUpBuf.clear();
    for (const [userId, delta] of usageSnap) {
        if (!delta) continue;
        if (_hawkUpColReady) {
            statements.push(env.IOT_DB.prepare(
                `INSERT INTO usage_bytes (user_id, total_bytes, day_bytes, last_day, month_bytes, last_month, month_up)
                 VALUES (?1, ?4, ?4, ?2, ?4, ?3, ?5)
                 ON CONFLICT(user_id) DO UPDATE SET
                     total_bytes = total_bytes + ?4,
                     day_bytes = CASE WHEN last_day = ?2 THEN day_bytes + ?4 ELSE ?4 END,
                     last_day = ?2,
                     month_up = CASE WHEN last_month = ?3 THEN COALESCE(month_up, 0) + ?5 ELSE ?5 END,
                     month_bytes = CASE WHEN last_month = ?3 THEN month_bytes + ?4 ELSE ?4 END,
                     last_month = ?3`,
            ).bind(userId, today, month, Math.round(delta), Math.round(upSnap.get(userId) || 0)));
            continue;
        }
        statements.push(
            env.IOT_DB.prepare(
                `INSERT INTO usage_bytes (user_id, total_bytes, day_bytes, last_day, month_bytes, last_month)
                 VALUES (?1, ?4, ?4, ?2, ?4, ?3)
                 ON CONFLICT(user_id) DO UPDATE SET
                     total_bytes = total_bytes + ?4,
                     day_bytes = CASE WHEN last_day = ?2 THEN day_bytes + ?4 ELSE ?4 END,
                     last_day = ?2,
                     month_bytes = CASE WHEN last_month = ?3 THEN month_bytes + ?4 ELSE ?4 END,
                     last_month = ?3`,
            ).bind(userId, today, month, Math.round(delta)),
        );
    }

    if (statements.length === 0) return;
    
    
    
    
    
    
    
    
    if (statements.length > MAX_FLUSH_STATEMENTS) {
        let usageCount = 0;
        for (const [, d] of usageSnap) if (d) usageCount++;
        const softCount = statements.length - usageCount;
        const keepSoft = Math.max(0, MAX_FLUSH_STATEMENTS - usageCount);
        if (softCount > keepSoft) {
            statements.splice(keepSoft, softCount - keepSoft);
        }
    }
    try {
        await env.IOT_DB.batch(statements);
    } catch (e) {
        
        
        
        
    }
}

async function loadAsnRelayStatsFromD1(env) {
    if (!env.IOT_DB) return new Map();
    await d1Init(env);
    try {
        const D1_TIMEOUT_MS = 4000;
        const timeout = new Promise((_, reject) =>
            setTimeout(() => reject(new Error("d1 timeout")), D1_TIMEOUT_MS),
        );
        const { results } = await Promise.race([
            env.IOT_DB.prepare(
                "SELECT asn, ip, success_count, fail_count, avg_bps FROM asn_relay_stats ORDER BY updated_at DESC LIMIT 2000",
            ).all(),
            timeout,
        ]);
        const map = new Map();
        if (results) {
            for (const row of results) {
                map.set(`${row.asn}:${row.ip}`, {
                    successes: row.success_count || 0,
                    fails: row.fail_count || 0,
                    avgBps: row.avg_bps || 0,
                });
            }
        }
        return map;
    } catch (e) {
        
        
        
        
        
        
        throw e;
    }
}




