async function sendAdminAlert(text) {
    if (!sysConfig.tgToken || !(sysConfig.tgAdminId || sysConfig.tgChatId))
        return;
    try {
        const tgApi = `https://api.telegram.org/bot${sysConfig.tgToken}`;
        await fetch(`${tgApi}/sendMessage`, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
                chat_id: sysConfig.tgAdminId || sysConfig.tgChatId,
                text,
                parse_mode: "Markdown",
            }),
            signal: AbortSignal.timeout(8000),
        });
    } catch (e) {}
}







const NETWORK_ALERT_WINDOW_MS = 300000; 
const NETWORK_ALERT_MIN_SAMPLES = 8;
const NETWORK_ALERT_FAIL_RATE = 0.5;
const NETWORK_ALERT_COOLDOWN_MS = 1800000; 






const RECENT_OUTCOMES_MAX = 500;
function recordConnectOutcome(ok) {
    const now = Date.now();
    recentConnectOutcomes.push({ ok, ts: now });
    
    while (
        recentConnectOutcomes.length > 0 &&
        now - recentConnectOutcomes[0].ts > NETWORK_ALERT_WINDOW_MS
    ) {
        recentConnectOutcomes.shift();
    }
    
    
    
    while (recentConnectOutcomes.length > RECENT_OUTCOMES_MAX) {
        recentConnectOutcomes.shift();
    }
}
function checkNetworkHealthAndAlert(ctx) {
    const now = Date.now();
    if (now - lastNetworkAlertTime < NETWORK_ALERT_COOLDOWN_MS) return;
    if (recentConnectOutcomes.length < NETWORK_ALERT_MIN_SAMPLES) return;
    const fails = recentConnectOutcomes.filter((o) => !o.ok).length;
    const failRate = fails / recentConnectOutcomes.length;
    if (failRate < NETWORK_ALERT_FAIL_RATE) return;
    lastNetworkAlertTime = now;
    const msg =
        `⚠️ *وضعیت شبکه بد شده*\n\n` +
        `${(failRate * 100).toFixed(0)}٪ از ${recentConnectOutcomes.length} تلاش اخیر برای اتصال شکست خورده (۵ دقیقه‌ی گذشته).\n\n` +
        `شاید وقتشه IP تمیز جدید اضافه کنی یا relayها رو چک کنی.\n` +
        `برای جزئیات بیشتر: /netstatus`;
    ctx?.waitUntil(sendAdminAlert(msg).catch(() => {}));
}







const NET_ALERT_WINDOW_MS = 300000; 
const NET_ALERT_MIN_ATTEMPTS = 20; 
const NET_ALERT_COOLDOWN_MS = 1800000; 








let baselineFailureRate = 0.2; 
const BASELINE_EMA_ALPHA = 0.02;
function noteConnectionAttempt(env, ctx, success) {
    const now = Date.now();
    if (success) PAIN.setupOk++; else PAIN.setupFail++;
    baselineFailureRate =
        baselineFailureRate * (1 - BASELINE_EMA_ALPHA) +
        (success ? 0 : 1) * BASELINE_EMA_ALPHA;
    if (now - connAttemptWindow.windowStart > NET_ALERT_WINDOW_MS) {
        connAttemptWindow = { attempts: 0, failures: 0, windowStart: now };
    }
    connAttemptWindow.attempts++;
    if (!success) connAttemptWindow.failures++;

    
    
    
    const dynamicThreshold = Math.min(
        0.9,
        Math.max(0.4, baselineFailureRate * 2.5),
    );

    if (
        connAttemptWindow.attempts >= NET_ALERT_MIN_ATTEMPTS &&
        connAttemptWindow.failures / connAttemptWindow.attempts >=
            dynamicThreshold &&
        now - lastNetworkAlertTime > NET_ALERT_COOLDOWN_MS &&
        sysConfig.tgToken &&
        (sysConfig.tgAdminId || sysConfig.tgChatId)
    ) {
        lastNetworkAlertTime = now;
        const rate = (
            (connAttemptWindow.failures / connAttemptWindow.attempts) *
            100
        ).toFixed(0);
        const chatId = sysConfig.tgAdminId || sysConfig.tgChatId;
        const text =
            `⚠️ *هشدار وضعیت شبکه*\n\n` +
            `نرخ شکست اتصال در ۵ دقیقه‌ی اخیر: *${rate}٪* ` +
            `(${connAttemptWindow.failures} از ${connAttemptWindow.attempts} تلاش)\n\n` +
            `این می‌تونه نشونه‌ی یه موج جدید فیلترینگ باشه. ` +
            `بد نیست چند تا IP تمیز/relay جدید اضافه کنی.\n\n` +
            `برای جزئیات بیشتر: /netstatus`;
        ctx?.waitUntil(
            fetch(`https://api.telegram.org/bot${sysConfig.tgToken}/sendMessage`, {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({
                    chat_id: chatId,
                    text,
                    parse_mode: "Markdown",
                }),
            }).catch(() => {}),
        );
    }
}



const HAWK_LOADTEST_MJS = "#!/usr/bin/env node\n// Hawk 3-user load test (no dependencies, Node 18+; works in Termux: pkg install nodejs)\n// Simulates N users, each with video-like streams (long downloads, like YouTube/Instagram)\n// and browsing (short connections), through REAL configs from your subscription.\n//\n//   node hawk_loadtest.mjs --sub \"https://HOST/Shaahin?sub=Ai\" [options]\n//\n// Options:\n//   --sub URL            subscription link (repeat 3x for 3 different users; one = shared)\n//   --sub-file FILE      or a saved base64/plain sub file (if the sub URL is blocked for you)\n//   --users 3            simulated users            --video 2   video streams per user\n//   --browse 1           browsing loops per user    --duration 300  seconds\n//   --video-url URL      plain-http big file downloaded through the \x74unnel\n//   --browse-url URL     small plain-http URL (default gstatic generate_204)\n//   --video-seconds 60   each video stream reconnects after this (like a real client)\n//   --canary-url URL --canary-token T   poll /__hawk/canary?detail=1 every 30s\n//   --max-requests 3000  hard stop to protect the daily free-plan quota\n//   --out report.json\nimport net from \"node:net\";\nimport tls from \"node:tls\";\nimport crypto from \"node:crypto\";\nimport fs from \"node:fs\";\n\n// ---------------- args ----------------\nconst argv = process.argv.slice(2);\nconst opt = { sub: [], users: 3, video: 2, browse: 1, duration: 300, videoSeconds: 60,\n  videoUrl: \"http://speedtest.tele2.net/100MB.zip\", browseUrl: \"http://www.gstatic.com/generate_204\",\n  maxRequests: 3000, out: \"hawk_loadtest_report.json\", connectTimeout: 8000, stallMs: 10000 };\nfor (let i = 0; i < argv.length; i++) {\n  const k = argv[i].replace(/^--/, \"\"), v = argv[i + 1];\n  const camel = k.replace(/-([a-z])/g, (_, c) => c.toUpperCase());\n  if (k === \"sub\") { opt.sub.push(v); i++; }\n  else if (k === \"help\" || k === \"h\") { console.log(fs.readFileSync(new URL(import.meta.url)).toString().split(\"\\n\").slice(1, 22).join(\"\\n\")); process.exit(0); }\n  else if (camel in opt || [\"subFile\", \"canaryUrl\", \"canaryToken\"].includes(camel)) { opt[camel] = typeof opt[camel] === \"number\" ? Number(v) : v; i++; }\n  else { console.error(\"unknown option \" + argv[i]); process.exit(2); }\n}\nif (!opt.sub.length && !opt.subFile) { console.error(\"need --sub or --sub-file (see --help)\"); process.exit(2); }\n\n// ---------------- config parsing ----------------\nfunction decodeSub(text) {\n  text = text.trim();\n  if (!/^(\x76less|\x74rojan|\x76mess):\\/\\//m.test(text)) {\n    try { text = Buffer.from(text.replace(/\\s+/g, \"\"), \"base64\").toString(\"utf8\"); } catch {}\n  }\n  return text.split(/\\r?\\n/).map((l) => l.trim()).filter((l) => l.startsWith(\"\x76less://\"));\n}\nfunction parse\x56less(line) {\n  const u = new URL(line.replace(/^\x76less:/, \"http:\"));\n  const p = u.searchParams;\n  if ((p.get(\"type\") || \"tcp\") !== \"ws\") return null;\n  const addr = u.hostname.replace(/^\\[|\\]$/g, \"\");\n  if (addr === \"127.0.0.1\") return null; // info/fake entries\n  return {\n    uuid: decodeURIComponent(u.username), addr, port: Number(u.port || 443),\n    tls: (p.get(\"security\") || \"none\") === \"tls\",\n    sni: p.get(\"sni\") || p.get(\"host\") || addr, host: p.get(\"host\") || p.get(\"sni\") || addr,\n    path: p.get(\"path\") || \"/\", name: decodeURIComponent(u.hash.slice(1)),\n  };\n}\nasync function loadSubs() {\n  const lists = [];\n  if (opt.subFile) lists.push(decodeSub(fs.readFileSync(opt.subFile, \"utf8\")));\n  for (const s of opt.sub) {\n    const url = new URL(s);\n    url.searchParams.set(\"format\", \"base64\");\n    const r = await fetch(url, { headers: { \"User-Agent\": \"\x762rayNG/1.9 hawk-loadtest\" } });\n    if (!r.ok) throw new Error(`sub ${r.status}: ${(await r.text()).slice(0, 200)}`);\n    lists.push(decodeSub(await r.text()));\n  }\n  return lists.map((l) => l.map(parse\x56less).filter(Boolean)).filter((l) => l.length);\n}\n\n// ---------------- minimal WebSocket client (custom IP + SNI + Host) ----------------\nfunction wsOpen(cfg, timeoutMs) {\n  return new Promise((resolve, reject) => {\n    const t0 = Date.now();\n    const key = crypto.randomBytes(16).toString(\"base64\");\n    const onSock = () => {\n      sock.write(`GET ${cfg.path} HTTP/1.1\\r\\nHost: ${cfg.host}\\r\\nUpgrade: websocket\\r\\nConnection: Upgrade\\r\\n` +\n        `Sec-WebSocket-Key: ${key}\\r\\nSec-WebSocket-Version: 13\\r\\nUser-Agent: Mozilla/5.0 hawk-loadtest\\r\\n\\r\\n`);\n    };\n    const sock = cfg.tls\n      ? tls.connect({ host: cfg.addr, port: cfg.port, servername: cfg.sni, ALPNProtocols: [\"http/1.1\"], rejectUnauthorized: false }, onSock)\n      : net.connect({ host: cfg.addr, port: cfg.port }, onSock);\n    let buf = Buffer.alloc(0), done = false;\n    const timer = setTimeout(() => fail(new Error(\"timeout\")), timeoutMs);\n    function fail(e) { if (done) return; done = true; clearTimeout(timer); sock.destroy(); reject(e); }\n    sock.on(\"error\", fail);\n    let badStatus = 0, hdrEnd = -1;\n    const httpErr = () => {\n      const body = buf.slice(hdrEnd + 4).toString();\n      const cf = (body.match(/error code:?\\s*(\\d{4})|Error (\\d{4})/i) || []).slice(1).find(Boolean);\n      const e = new Error(`http-${badStatus}${cf ? \"-cf\" + cf : \"\"}`); e.status = badStatus; e.cf = cf; return e;\n    };\n    sock.on(\"close\", () => fail(badStatus ? httpErr() : new Error(buf.length ? \"closed-during-handshake\" : \"reset\")));\n    sock.on(\"data\", function onData(d) {\n      buf = Buffer.concat([buf, d]);\n      if (badStatus) return;\n      const end = buf.indexOf(\"\\r\\n\\r\\n\");\n      if (end < 0) return;\n      const head = buf.slice(0, end).toString();\n      const status = Number(head.split(\" \")[1]);\n      if (status !== 101) {\n        // keep reading a moment so Cloudflare error codes (1101/1102/1015) in the body are visible\n        badStatus = status || 1; hdrEnd = end;\n        setTimeout(() => fail(httpErr()), 300);\n        return;\n      }\n      done = true; clearTimeout(timer);\n      sock.removeListener(\"data\", onData);\n      sock.removeAllListeners(\"close\"); sock.removeAllListeners(\"error\");\n      resolve(new WS(sock, buf.slice(end + 4), Date.now() - t0));\n    });\n  });\n}\nclass WS {\n  constructor(sock, rest, ms) {\n    this.sock = sock; this.connectMs = ms; this.buf = Buffer.alloc(0);\n    this.onmessage = null; this.onclose = null; this.closed = false;\n    sock.on(\"data\", (d) => this._feed(d));\n    sock.on(\"close\", () => this._closed(\"closed\"));\n    sock.on(\"error\", (e) => this._closed(e.code || \"error\"));\n    if (rest.length) this._feed(rest);\n  }\n  _closed(why) { if (this.closed) return; this.closed = true; this.onclose && this.onclose(why); }\n  _feed(d) {\n    this.buf = Buffer.concat([this.buf, d]);\n    for (;;) {\n      if (this.buf.length < 2) return;\n      const op = this.buf[0] & 15, masked = this.buf[1] & 128;\n      let len = this.buf[1] & 127, off = 2;\n      if (len === 126) { if (this.buf.length < 4) return; len = this.buf.readUInt16BE(2); off = 4; }\n      else if (len === 127) { if (this.buf.length < 10) return; len = Number(this.buf.readBigUInt64BE(2)); off = 10; }\n      const mOff = off; if (masked) off += 4;\n      if (this.buf.length < off + len) return;\n      let payload = this.buf.slice(off, off + len);\n      if (masked) { const m = this.buf.slice(mOff, mOff + 4); payload = Buffer.from(payload.map((b, i) => b ^ m[i & 3])); }\n      this.buf = this.buf.slice(off + len);\n      if (op === 8) { this.close(); this._closed(\"ws-close\"); return; }\n      if (op === 9) this._send(10, payload);\n      else if (op === 1 || op === 2 || op === 0) this.onmessage && this.onmessage(payload);\n    }\n  }\n  _send(op, data) {\n    if (this.closed) return;\n    const len = data.length, mask = crypto.randomBytes(4);\n    let head;\n    if (len < 126) head = Buffer.from([128 | op, 128 | len]);\n    else if (len < 65536) { head = Buffer.alloc(4); head[0] = 128 | op; head[1] = 128 | 126; head.writeUInt16BE(len, 2); }\n    else { head = Buffer.alloc(10); head[0] = 128 | op; head[1] = 128 | 127; head.writeBigUInt64BE(BigInt(len), 2); }\n    const body = Buffer.from(data.map((b, i) => b ^ mask[i & 3]));\n    this.sock.write(Buffer.concat([head, mask, body]));\n  }\n  send(data) { this._send(2, data); }\n  close() { try { this._send(8, Buffer.alloc(0)); } catch {} try { this.sock.end(); setTimeout(() => this.sock.destroy(), 500); } catch {} }\n}\n\n// ---------------- \x56LESS over WS ----------------\nfunction \x76lessHeader(uuid, host, port) {\n  const id = Buffer.from(uuid.replace(/-/g, \"\"), \"hex\");\n  const h = Buffer.from(host);\n  return Buffer.concat([Buffer.from([0]), id, Buffer.from([0, 1]), Buffer.from([port >> 8, port & 255, 2, h.length]), h]);\n}\nlet requestsUsed = 0;\nasync function \x74unnelHttp(cfg, targetUrl, { maxMs, onBytes }) {\n  if (requestsUsed >= opt.maxRequests) throw new Error(\"quota-guard\");\n  requestsUsed++;\n  const t = new URL(targetUrl);\n  const port = Number(t.port || 80);\n  const ws = await wsOpen(cfg, opt.connectTimeout);\n  const req = `GET ${t.pathname}${t.search} HTTP/1.1\\r\\nHost: ${t.host}\\r\\nUser-Agent: hawk-loadtest\\r\\nAccept: */*\\r\\nConnection: close\\r\\n\\r\\n`;\n  ws.send(Buffer.concat([\x76lessHeader(cfg.uuid, t.hostname, port), Buffer.from(req)]));\n  return await new Promise((resolve) => {\n    const r = { connectMs: ws.connectMs, ttfbMs: null, bytes: 0, stalls: 0, end: \"ok\", firstLine: \"\", httpStatus: null };\n    const t0 = Date.now(); let responseHeader = Buffer.alloc(0), responseReady = false, lastData = Date.now(), stalled = false;\n    const tick = setInterval(() => {\n      const idle = Date.now() - lastData;\n      if (idle > opt.stallMs && !stalled) { stalled = true; r.stalls++; }\n      if (Date.now() - t0 > maxMs) finish(\"time-limit\");\n      if (r.ttfbMs === null && Date.now() - t0 > 15000) finish(\"no-response\");\n      if (idle > 30000) finish(\"stalled-30s\");\n    }, 1000);\n    function finish(why) { clearInterval(tick); if (r.end === \"ok\") r.end = why; r.ms = Date.now() - t0; ws.close(); resolve(r); }\n    ws.onmessage = (d) => {\n      if (!responseReady) {\n        responseHeader = Buffer.concat([responseHeader, Buffer.from(d)]);\n        if (responseHeader.length < 2) return;\n        const addLen = responseHeader[1];\n        const skip = 2 + addLen;\n        if (responseHeader.length < skip) return;\n        d = responseHeader.slice(skip);\n        responseReady = true;\n      }\n      if (!d.length) return;\n      if (r.ttfbMs === null) {\n        r.ttfbMs = Date.now() - t0;\n        r.firstLine = d.slice(0, 80).toString().split(\"\\r\\n\")[0];\n        const m = r.firstLine.match(/^HTTP\\/\\d(?:\\.\\d)?\\s+(\\d{3})/);\n        r.httpStatus = m ? Number(m[1]) : null;\n        if (r.httpStatus && r.httpStatus >= 400) r.end = \"target-http-\" + r.httpStatus;\n      }\n      r.bytes += d.length; lastData = Date.now(); stalled = false; onBytes && onBytes(d.length);\n    };\n    ws.onclose = (why) => finish(r.ttfbMs === null ? \"closed-before-data:\" + why : (why === \"ws-close\" || why === \"closed\" ? \"done\" : why));\n  });\n}\n\n// ---------------- workload ----------------\nconst stats = []; // {user, kind, cfg, ...}\nconst errors = {};\nconst live = { bytes: 0, open: 0 };\nfunction noteErr(e) { const k = e.message || String(e); errors[k] = (errors[k] || 0) + 1; return k; }\nconst sleep = (ms) => new Promise((r) => setTimeout(r, ms));\nlet stop = false;\n\nasync function videoLoop(user, cfgs, idx) {\n  let n = 0;\n  while (!stop) {\n    const cfg = cfgs[(idx + n++) % cfgs.length];\n    live.open++;\n    try {\n      const r = await \x74unnelHttp(cfg, opt.videoUrl, { maxMs: opt.videoSeconds * 1000, onBytes: (b) => (live.bytes += b) });\n      stats.push({ user, kind: \"video\", cfg: cfg.name, ...r, mbps: +(r.bytes * 8 / 1e6 / Math.max(1, (r.ms || 1000) / 1000)).toFixed(2) });\n      if (!/^(time-limit|done|ok)$/.test(r.end)) noteErr(new Error(\"video-\" + r.end));\n    } catch (e) {\n      stats.push({ user, kind: \"video\", cfg: cfg.name, fail: noteErr(e) });\n      await sleep(2000);\n    } finally { live.open--; }\n  }\n}\nasync function browseLoop(user, cfgs, idx) {\n  let n = 0;\n  while (!stop) {\n    const cfg = cfgs[(idx + n++) % cfgs.length];\n    try {\n      const r = await \x74unnelHttp(cfg, opt.browseUrl, { maxMs: 15000 });\n      stats.push({ user, kind: \"browse\", cfg: cfg.name, ...r });\n      if (r.ttfbMs === null) noteErr(new Error(\"browse-\" + r.end));\n    } catch (e) { stats.push({ user, kind: \"browse\", cfg: cfg.name, fail: noteErr(e) }); }\n    await sleep(3000 + Math.random() * 2000);\n  }\n}\nconst canarySamples = [];\nasync function canaryLoop() {\n  if (!opt.canaryUrl || !opt.canaryToken) return;\n  while (!stop) {\n    try {\n      const u = new URL(opt.canaryUrl); u.searchParams.set(\"detail\", \"1\");\n      const r = await fetch(u, { headers: { \"x-hawk-canary\": opt.canaryToken } });\n      const j = await r.json().catch(() => null);\n      canarySamples.push({ t: Date.now(), status: r.status, ok: j?.ok, gov: j?.governor, conns: j?.activeConnections, brk: j?.breaker, routes: j?.breakerRoutes });\n    } catch (e) { canarySamples.push({ t: Date.now(), error: e.message }); }\n    await sleep(30000);\n  }\n}\n\n// ---------------- report ----------------\nconst pct = (a, p) => { if (!a.length) return null; const s = [...a].sort((x, y) => x - y); return s[Math.min(s.length - 1, Math.floor(p / 100 * s.length))]; };\nfunction report(started) {\n  const ok = stats.filter((s) => !s.fail), bad = stats.filter((s) => s.fail);\n  const cfErr = Object.keys(errors).filter((k) => /cf11\\d\\d|http-5\\d\\d|http-404/.test(k));\n  const vid = ok.filter((s) => s.kind === \"video\"), br = ok.filter((s) => s.kind === \"browse\");\n  const conn = ok.map((s) => s.connectMs), ttfb = ok.map((s) => s.ttfbMs).filter((x) => x != null);\n  const failRate = stats.length ? bad.length / stats.length : 1;\n  const stalls = vid.reduce((a, s) => a + s.stalls, 0);\n  const drops = vid.filter((s) => !/^(time-limit|done|ok)$/.test(s.end)).length;\n  const sum = {\n    durationSec: Math.round((Date.now() - started) / 1000), users: opt.users,\n    workerRequestsUsed: requestsUsed,\n    \x74unnels: stats.length, failed: bad.length, failRatePct: +(failRate * 100).toFixed(1),\n    connectMs: { p50: pct(conn, 50), p95: pct(conn, 95) }, ttfbMs: { p50: pct(ttfb, 50), p95: pct(ttfb, 95) },\n    video: { sessions: vid.length, avgMbps: vid.length ? +(vid.reduce((a, s) => a + s.mbps, 0) / vid.length).toFixed(2) : 0,\n      minMbps: vid.length ? Math.min(...vid.map((s) => s.mbps)) : 0, stalls, midStreamDrops: drops },\n    browse: { requests: br.length, ttfbP95: pct(br.map((s) => s.ttfbMs).filter((x) => x != null), 95) },\n    errors, cloudflareErrors: cfErr,\n    governorSeen: [...new Set(canarySamples.map((c) => c.gov).filter(Boolean))],\n    maxBreakerOpen: Math.max(0, ...canarySamples.map((c) => c.brk?.open || 0)),\n  };\n  const verdict = [];\n  const targetErr = stats.filter((s) => s.httpStatus && s.httpStatus >= 400).map((s) => s.httpStatus);\n  if (targetErr.length) verdict.push(\"WARN: target HTTP errors \" + [...new Set(targetErr)].join(\", \"));\n  if (cfErr.length) verdict.push(\"FAIL: Cloudflare/worker errors \" + cfErr.join(\", \"));\n  if (failRate > 0.05) verdict.push(`FAIL: ${sum.failRatePct}% \x74unnels failed (>5%)`);\n  if (vid.length && stalls > vid.length * 0.2) verdict.push(`WARN: ${stalls} video stalls (>10s no data)`);\n  if (drops) verdict.push(`WARN: ${drops} video streams dropped mid-stream`);\n  if (sum.connectMs.p95 > 3000) verdict.push(`WARN: slow connect p95=${sum.connectMs.p95}ms`);\n  sum.verdict = verdict.length ? verdict : [\"PASS\"];\n  fs.writeFileSync(opt.out, JSON.stringify({ summary: sum, canary: canarySamples, samples: stats }, null, 2));\n  return sum;\n}\n\n// ---------------- main ----------------\nconst lists = await loadSubs().catch((e) => { console.error(\"could not load sub: \" + e.message); process.exit(1); });\nif (!lists.length) { console.error(\"no usable \x76less+ws configs in the sub\"); process.exit(1); }\nconst est = Math.round(opt.users * (opt.video * opt.duration / opt.videoSeconds + opt.browse * opt.duration / 4));\nconsole.log(`Hawk load test: ${opt.users} users x (${opt.video} video + ${opt.browse} browse), ${opt.duration}s`);\nconsole.log(`configs: ${lists.map((l) => l.length).join(\"/\")}  est. worker requests ~${est} (guard ${opt.maxRequests})`);\nconst started = Date.now();\nconst jobs = [];\nfor (let u = 0; u < opt.users; u++) {\n  const cfgs = lists[u % lists.length];\n  for (let v = 0; v < opt.video; v++) jobs.push(videoLoop(u + 1, cfgs, u * 7 + v));\n  for (let b = 0; b < opt.browse; b++) jobs.push(browseLoop(u + 1, cfgs, u * 7 + 3 + b));\n}\njobs.push(canaryLoop());\nlet lastBytes = 0;\nconst prog = setInterval(() => {\n  const mbps = ((live.bytes - lastBytes) * 8 / 1e6 / 5).toFixed(1); lastBytes = live.bytes;\n  const f = stats.filter((s) => s.fail).length;\n  const c = canarySamples[canarySamples.length - 1];\n  console.log(`[${Math.round((Date.now() - started) / 1000)}s] streams=${live.open} total=${mbps}Mbps \x74unnels=${stats.length} fail=${f} req=${requestsUsed}` +\n    (c && c.gov ? ` gov=${c.gov} brkOpen=${c.brk?.open}` : \"\"));\n}, 5000);\nawait sleep(opt.duration * 1000);\nstop = true; clearInterval(prog);\nawait Promise.race([Promise.allSettled(jobs), sleep(opt.videoSeconds * 1000 + 5000)]);\nconst s = report(started);\nconsole.log(\"\\n===== RESULT =====\");\nconsole.log(JSON.stringify(s, null, 2));\nconsole.log(`full report: ${opt.out}`);\nprocess.exit(0);\n";


async function hawkCanary(env, ctx, url) {
    const t0 = Date.now();
    const checks = {};
    let ok = true;
    const step = async (name, fn) => {
        try {
            const r = await Promise.race([
                fn(),
                new Promise((_, rej) => setTimeout(() => rej(new Error("timeout")), 3000)),
            ]);
            checks[name] = r === undefined ? true : r;
            if (r === false) ok = false;
        } catch (e) {
            checks[name] = "FAIL: " + String((e && e.message) || e).slice(0, 120);
            ok = false;
        }
    };
    await step("d1", async () => {
        if (!env.IOT_DB) return "no-binding";
        const r = await env.IOT_DB.prepare("SELECT 1 AS x").first();
        return !!(r && r.x === 1);
    });
    await step("config", async () => {
        await loadSysConfig(env, ctx);
        activeDeviceId = sysConfig.deviceId || generateHardwareId(sysConfig.apiRoute);
        return !!(sysConfig && sysConfig.apiRoute && activeDeviceId);
    });
    const testSub =
        url.searchParams.get("sub") ||
        (sysConfig.users && sysConfig.users[0] && sysConfig.users[0].name) ||
        null;
    checks.testedSub = testSub || "Default";
    await step("sub_uri", async () => {
        const host = url.hostname;
        const raw = await buildUriProfile(host, testSub, false, null, null, false, false);
        const lines = raw.split("\n").filter((l) => /^(\x76less|\x74rojan):\/\//.test(l));
        if (lines.length === 0) throw new Error("no config lines");
        const bad = [];
        let real = 0;
        for (const l of lines) {
            let why = null;
            try {
                const u = new URL(l.replace(/^(\x76less|\x74rojan):/, "http:"));
                const port = Number(u.port || 443);
                if (u.hostname === "127.0.0.1") continue; 
                real++;
                if (!u.username) why = "no-uuid";
                else if (!u.hostname || /undefined|NaN|\[\[/.test(u.hostname)) why = "bad-host";
                else if (!(port > 0 && port < 65536)) why = "bad-port";
                else if (/undefined|NaN/.test(u.search)) why = "bad-params";
            } catch (e) { why = "unparsable"; }
            if (why) bad.push(why + ": " + l.split("#")[1]?.slice(0, 40) + " @" + (l.split("@")[1] || "").split("?")[0]);
        }
        if (real === 0) throw new Error("only info entries, no real configs");
        if (bad.length) throw new Error(bad.length + "/" + real + " broken, e.g. " + bad[0]);
        const named = lines.filter((l) => /undefined|NaN/.test(decodeURIComponent((l.split("#")[1] || "").replace(/%(?![0-9A-Fa-f]{2})/g, "%25")))).length;
        const warn = [];
        if (named) warn.push(named + " names contain undefined");
        if (real > 1000) warn.push("too many configs (" + real + "): set Max Configs, clients get slow");
        return warn.length ? real + " (warn: " + warn.join("; ") + ")" : real;
    });
    await step("sub_\x73ingbox", async () => {
        const j = await build\u0053ingBoxJsonProfile(url.hostname, testSub, false, null);
        const s2 = JSON.stringify(j);
        return Array.isArray(j.outbounds) && j.outbounds.length > 0 && s2.indexOf("{all_proxies}") === -1 && s2.indexOf("__OUTBOUNDS__") === -1;
    });
    await step("sub_vjson", async () => {
        const arr = await buildVJsonProfile(url.hostname, testSub, false, null, true, null);
        if (!Array.isArray(arr) || !arr.length) return false;
        return arr.every((j) => {
            const rules = (j.routing && j.routing.rules) || [];
            const last = rules[rules.length - 1];
            const ob = last && j.outbounds.find((o) => o && o.tag === last.outboundTag);
            return !!(j.remarks && ob && ob.protocol !== "freedom" && j.inbounds && j.inbounds.length);
        }) ? arr.length : false;
    });
    await step("no_upstream_refs", async () => {
        const h = localizePanelAssets(rebrandHtml(EMBEDDED_DASHBOARD_HTML_2));
        return !/hawk-project|cdn-assets/.test(h);
    });
    const body = {
        ok,
        version: CURRENT_VERSION,
        ms: Date.now() - t0,
        checks,
        governor: GOV_NAMES[govLevel()],
        qos: hawkQosView(),
        breaker: brkStats(),
        breakerRoutes: url.searchParams.get("detail") === "1" ? brkOpenList(50) : undefined,
        relayScoring: url.searchParams.get("detail") === "1" ? relayScoringList(30) : undefined,
        isolateUptimeSec: isolateStartTime ? Math.round((Date.now() - isolateStartTime) / 1000) : 0,
        activeConnections,
        relayHealth: RH.size,
        recycle: { pauseRecycles: recycleStats.pause, hardRecycles: recycleStats.hard, budgetMb: Math.round(hawkRecycleBudgetBytes(govLevel()) / 1048576) },
        off: [..._hawkOff],
        flags: [..._hawkOn],
    };
    return new Response(JSON.stringify(body), {
        status: ok ? 200 : 503,
        headers: { "Content-Type": "application/json", "Cache-Control": "no-store" },
    });
}













const RH = new Map();
const RH_MAX = 1500;
const RH_QUAR_STEPS_MS = [120000, 600000, 1800000, 7200000]; 
const RH_GRAVE_PROBE_MS = 1800000;      
const RH_GRAVE_RESURRECT_OKS = 3;       
