    if (!st.canManage) return { success: op !== "enable", ...st, error: op === "enable" ? "Account ID + API Token + Worker name رو تو تنظیمات پنل بزن (یا دستی: Settings → Triggers → Cron */10 * * * *)" : undefined };
    const base = `https://api.cloudflare.com/client/v4/accounts/${acc}/workers/scripts/${encodeURIComponent(name)}/schedules`;
    const H = { Authorization: "Bearer " + tok, "Content-Type": "application/json" };
