    if (r.changedAt >= ts) return; 
    if (r.state !== "HEALTHY" && r.state !== "DEGRADED" && st !== "QUARANTINE" && st !== "GRAVEYARD") return;
    r.score = Math.min(r.score, score);
    r.level = Math.max(r.level, level || 0);
    r.until = until || 0;
    r.nextProbe = nextProbe || 0;
    if (port) r.port = port;
    r.state = st;
    r.changedAt = ts;
