async function probeRelayCandidate(env, ctx, hostname, port = 443) {
    const PROBE_TIMEOUT_MS = 5000;
    const start = Date.now();
    let sock;
    try {
        sock = connect({ hostname, port });
        sock.closed.catch(() => {});
        const timeout = new Promise((_, reject) =>
            setTimeout(() => reject(new Error("probe timeout")), PROBE_TIMEOUT_MS),
        );
        await Promise.race([sock.opened, timeout]);
        recentlyFailedRelays.delete(hostname);
        noteConnectionAttempt(env, ctx, true);
        const elapsed = Date.now() - start;
        relayHealthOnSuccess(hostname, elapsed, true);
        noteRelayLatency(hostname, elapsed);
        
        
        
        void elapsed;
    } catch (e) {
        recentlyFailedRelays.set(hostname, Date.now() + relayHealthOnFailure(hostname, e, true, port));
        noteConnectionAttempt(env, ctx, false);
        bufferRelayFailure(hostname);
        maybeFlushStatsBuffers(env, ctx);
    } finally {
        try {
            sock?.close();
        } catch (e2) {}
    }
}





async function resolveDomainViaDoh(domain) {
    const dohEndpoints = [
        sysConfig.customDns,
        "https://cloudflare-dns.com/dns-query",
        "https://dns.google/resolve",
        "https://unfiltered.adguard-dns.com/resolve",
    ].filter((v, i, arr) => v && arr.indexOf(v) === i);

    const dohLookup = async (endpoint) => {
        const dohUrl = new URL(endpoint);
        dohUrl.searchParams.set("name", domain);
        dohUrl.searchParams.set("type", "A");
        const dnsRes = await fetch(dohUrl.toString(), {
            headers: { accept: "application/dns-json" },
            signal: AbortSignal.timeout(5000),
        });
        const dnsJson = await dnsRes.json();
        if (dnsJson.Answer && dnsJson.Answer.length > 0) {
            return dnsJson.Answer[0].data;
        }
        throw new Error("no DNS answer");
    };

    return await Promise.any(dohEndpoints.map((endpoint) => dohLookup(endpoint)));
}

async function d1Get(env, key) {
    if (!env.IOT_DB) return null;
    await d1Init(env);
    try {
        const D1_TIMEOUT_MS = 4000;
        const timeout = new Promise((_, reject) =>
            setTimeout(() => reject(new Error("d1 timeout")), D1_TIMEOUT_MS),
        );
        const { results } = await Promise.race([
            env.IOT_DB.prepare("SELECT value FROM kv_store WHERE key = ?")
                .bind(key)
                .all(),
            timeout,
        ]);
        if (results && results.length > 0) return results[0].value;
    } catch (e) {}
    return null;
}




















async function edgeCacheGetText(cacheKeyName) {
    try {
        const cache = caches.default;
        const cached = await cache.match(
            new Request(`https://internal-cache.hawk-worker.local/${cacheKeyName}`),
        );
        if (cached) return await cached.text();
    } catch (e) {}
    return null;
}
async function edgeCachePutText(cacheKeyName, value, ttlSeconds, ctx) {
    try {
        const cache = caches.default;
        const resp = new Response(value, {
            headers: { "Cache-Control": `public, max-age=${ttlSeconds}` },
        });
        const p = cache.put(
            new Request(`https://internal-cache.hawk-worker.local/${cacheKeyName}`),
            resp,
        );
        if (ctx && typeof ctx.waitUntil === "function") ctx.waitUntil(p.catch(() => {}));
        else await p.catch(() => {});
    } catch (e) {}
}

