async function d1PutStrict(env, key, value) {
    if (!env.IOT_DB) throw new Error("D1 binding IOT_DB is missing");
    if (hawkD1BreakerOpen()) throw new Error("D1 breaker open");
    try {
        await d1Init(env);
        if (hawkD1BreakerOpen()) throw new Error("D1 breaker open");
        const D1_TIMEOUT_MS = 4000;
    const withTimeout = (p) =>
        Promise.race([
            p,
            new Promise((_, reject) =>
                setTimeout(() => reject(new Error("d1 timeout")), D1_TIMEOUT_MS),
            ),
        ]);
    await withTimeout(
        env.IOT_DB.prepare(
            "INSERT INTO kv_store (key, value) VALUES (?, ?) ON CONFLICT(key) DO UPDATE SET value=excluded.value",
        )
            .bind(key, value)
            .run(),
    );
    const { results } = await withTimeout(
        env.IOT_DB.prepare("SELECT value FROM kv_store WHERE key = ?")
            .bind(key)
            .all(),
    );
        if (!results || results.length === 0 || results[0].value !== value) {
            throw new Error("write was not persisted (read-back mismatch)");
        }
        hawkD1BreakerOk();
    } catch (e) {
        hawkD1BreakerFail();
        throw e;
    }
}








async function cachedD1Put(env, key, value, strict = false) {
    if (key !== "sys_config") {
        await d1Put(env, key, value);
        if (key === "sys_usage") sysUsageCacheTime = 0;
        else if (key === "backup_ip") {
            backupIpCacheTime = 0;
            
            await edgeCachePutText("kv:backup_ip", value == null ? EDGE_NULL : String(value), 120, null);
        }
        return;
    }
    let pendingRevision = null;
    try {
        const next = JSON.parse(value);
        pendingRevision = crypto.randomUUID();
        next.__hawkConfigRevision = pendingRevision;
        value = JSON.stringify(next);
    } catch (e) { hawkLogErr("cachedD1Put", e); }
    try {
        await d1PutStrict(env, key, value);
    } catch (e) {
        console.error("sys_config save failed:", e && e.message ? e.message : e);
        if (strict) {
            
            
            sysConfigCacheTime = 0;
            throw e;
        }
        return;
    }
    sysConfigCacheTime = 0;
    if (pendingRevision) {
        configRevision = pendingRevision;
        sysConfig.__hawkConfigRevision = pendingRevision;
    }
    
    
    await edgeCachePutText("kv:sys_config", value, 150, null);
    sysConfigLkgPut(value, true);
    return value;
}








async function refreshSysConfigFresh(env) {
    if (!env.IOT_DB) return false;
    try {
        const stored = await d1GetStrict(env, "sys_config", { bypassEdge: true });
        sysConfig = {
            ...SYSTEM_DEFAULTS,
            ...(stored ? JSON.parse(stored) : null),
        };
        normalizeMuxConfig(sysConfig);
        configRevision = sysConfig.__hawkConfigRevision || "legacy";
        if (Array.isArray(sysConfig.users)) for (const u of sysConfig.users) {
            u.protocols = normalizeUserProtocols(u.protocols);
            u.fragmentPreset = normalizeUserFragment(u.fragmentPreset);
            if (u.userPorts) u.userPorts = userPortsString(u.userPorts, sysConfig.socketPorts);
        }
        sysConfig.customRelay = backupIpCache ?? env.RELAY_IP ?? "";
        sysConfigCacheTime = Date.now();
        sysConfigEverLoadedSuccessfully = true;
        
        
        return true;
    } catch (e) {
        return false;
    }
}











async function loadMapViaEdgeCache(cacheKeyName, edgeTtlSeconds, loaderFn) {
    const cached = await edgeCacheGetText(cacheKeyName);
    if (cached !== null) {
        try {
            return new Map(JSON.parse(cached));
        } catch (e) {}
    }
    const map = await loaderFn();
    try {
        const serializable = JSON.stringify(Array.from(map.entries()));
        edgeCachePutText(cacheKeyName, serializable, edgeTtlSeconds, null);
    } catch (e) {}
    return map;
}

