    const client = {
        readyState: 1,
        addEventListener(type, fn) { if (type === "message") listener = fn; },
        send(data) { if (!closed) writer.write(data instanceof Uint8Array ? data : new Uint8Array(data)).catch(()=>{}); },
        close() { if (!closed) { closed = true; writer.close().catch(()=>{}); } },
    };
    const pipe = startDataPipe(client, env, ctx, relayIdx, request.cf?.asn || null, null, null, request.cf?.asOrganization || null, "chrome").catch(()=>client.close());
    const waitL = async()=>{for(let i=0;i<200&&!listener&&!closed;i++)await new Promise(r=>setTimeout(r,10));return listener;};
    
    const pump = (async()=>{try{const reader=request.body.getReader();while(true){const {done,value}=await reader.read();if(done)break;const L=listener||await waitL();if(L&&!closed)await L({data:value.buffer.slice(value.byteOffset,value.byteOffset+value.byteLength)});}}catch(e){}finally{if(!closed)client.close();}})();
