        const _on = (k) => { const sl = hawkCronSlot(event); return sl < 0 || sl === k; };
        try { if (_on(0)) ctx.waitUntil(hgPruneRows(env).catch((_e) => hawkLogErr("scheduled", _e))); } catch (e) { hawkLogErr("scheduled", e); }
        let _r; try { _r = await hawkWorker.scheduled(event, env, ctx); } catch (e) { hawkLogErr("scheduled", e); }
