class HawkCronSkip extends Error {}
function hawkCronSlot(event) {
    try {
        if (sysConfig && sysConfig.cronRotate === false) return -1;
        if (event && Number.isInteger(event.__slot)) return event.__slot;
        const t = Number(event && event.scheduledTime);
        if (!(t > 0)) return -1;
        return Math.floor((t > 1e12 ? t / 1000 : t) / 300) % 5;
    } catch (e) { return -1; }
}
const HAWK_REQ_WATCHDOG_MS = 25000;
let _hawkBootAt = 0; 
function hawkSafeFallback(request, err) {
    try { return hgFallback(request, err); } catch (e) {}
    try { if (new URL(request.url).pathname === "/") return decoyFallback(); } catch (e) {}
    return new Response('{"success":false,"error":"Hawk is recovering, retry in a moment","retry":true}', { status: 500, headers: { "Content-Type": "application/json", "Cache-Control": "no-store", "Retry-After": "2" } });
}
async function maybeSendDailyReport(env, event) {
    const t = new Date((event && event.scheduledTime) || Date.now());
    if (t.getUTCHours() !== 4 || t.getUTCMinutes() >= 5) return;
    if (!sysConfig.tgToken || !env.IOT_DB) return;
    const users = sysConfig.users || [];
    const now = Date.now();
    const activeUsers = users.filter((u) => !u.isPaused && !(u.expiryMs && now > u.expiryMs)).length;
    let lines = [`📊 *گزارش روزانه Hawk v${CURRENT_VERSION}*`, `کاربرها: ${activeUsers} فعال از ${users.length}`];
    try {
        await d1Init(env);
        const { results } = await env.IOT_DB.prepare(
            `SELECT asn, COUNT(*) AS n, SUM(CASE WHEN last_ok > ?1 THEN 1 ELSE 0 END) AS alive
             FROM asn_cleanip_stats GROUP BY asn ORDER BY alive DESC LIMIT 6`,
        ).bind(now - 24 * 3600 * 1000).all();
        if (results && results.length) {
            lines.push("", "Clean IP سالم در ۲۴ ساعت گذشته:");
            for (const r of results) {
                const net = IR_ASN_NAMES[String(r.asn)] || `ASN ${r.asn}`;
                lines.push(`• ${_tgEsc(net)}: ${r.alive || 0} از ${r.n}`);
            }
        }
        let q = 0, g = 0, fl = 0;
        for (const [, r] of RH) { if (r.state === "QUARANTINE") q++; else if (r.state === "GRAVEYARD") g++; if (r.flapUntil > now) fl++; }
        lines.push(`رله‌ها: ${q} قرنطینه، ${g} قبرستان، ${fl} ناپایدار`);
        const dead = await loadCleanIpDeadGlobal(env);
        lines.push(`حذف‌شده از ساب (روی همه‌ی شبکه‌ها خراب): ${dead.size}`);
    } catch (e) {
        lines.push("D1: خطا در خواندن آمار");
    }
    await sendAdminAlert(lines.join("\n"));
}












let _decoyDownUntil = 0;
const DECOY_FALLBACK_HTML = `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ubuntu</title><style>body{margin:0;background:#300a24;color:#fff;font:16px system-ui;display:grid;place-items:center;min-height:100vh}.box{text-align:center;padding:32px}h1{font-size:42px;margin:0 0 10px}p{opacity:.8}</style></head><body><main class="box"><h1>Ubuntu</h1><p>Welcome to Ubuntu</p></main></body></html>`;
function decoyFallback() {
    return new Response(DECOY_FALLBACK_HTML, { status: 200, headers: { "Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-store" } });
}
async function serveMaintenancePage(request, url) {
    if (request.headers.get("x-hawk-selftest") === "1") return new Response("<!doctype html><title>Ubuntu</title><h1>Ubuntu</h1>", { status: 200, headers: { "Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-store" } });
    if (request.headers.get("x-fwd-depth")) return decoyFallback();
    if (Date.now() < _decoyDownUntil) return decoyFallback();
    const raw = String(sysConfig.maintenanceHost || "https://www.ubuntu.com,https://www.docker.com");
    const decoys = raw.split(",").map((x) => x.trim()).filter(Boolean).map((x) => /^https?:\/\//i.test(x) ? x : "https://" + x);
    const selfHost = String(url.hostname || "").toLowerCase();
    const targets = (decoys.length ? decoys : ["https://www.ubuntu.com", "https://www.docker.com"]).filter((t) => {
        try { return new URL(t).hostname.toLowerCase() !== selfHost; } catch (e) { return false; }
    });
    if (!targets.length) return decoyFallback();
    const isRoot = request.method === "GET" && url.pathname === "/" && !url.search;
    if (isRoot) {
        const hit = await edgeCacheGetText("decoy_root_v1");
        if (hit) {
            try {
                const j = JSON.parse(hit);
                if (j && typeof j.b === "string" && j.b.length) return new Response(j.b, { status: 200, headers: { "Content-Type": j.t || "text/html; charset=utf-8", "Cache-Control": "no-store" } });
            } catch (e) {}
        }
    }
    const allowed = new Set(["user-agent", "accept", "accept-language"]);
    const forwarded = new Headers();
    for (const [k, v] of request.headers) if (allowed.has(k.toLowerCase())) forwarded.set(k, v);
    forwarded.set("user-agent", forwarded.get("user-agent") || "Mozilla/5.0");
    forwarded.set("accept", forwarded.get("accept") || "text/html,application/xhtml+xml");
    forwarded.set("accept-language", forwarded.get("accept-language") || "en-US,en;q=0.9");
    forwarded.set("x-fwd-depth", "1");
    const path = url.pathname === "/" ? "/" : url.pathname;
    const started = Date.now();
    let hardFails = 0;
    for (const target of targets) {
        if (Date.now() - started > (isRoot ? 6000 : 4500)) break;
        try {
            const u = new URL(target);
            u.pathname = path;
            u.search = url.search;
            const r = await fetch(u.toString(), {
                method: request.method === "HEAD" ? "HEAD" : "GET",
                headers: forwarded,
                redirect: "follow",
                signal: AbortSignal.timeout(isRoot ? Math.max(1000, Math.min(3500, 6000 - (Date.now() - started))) : 4000),
                cf: request.method === "GET" ? { cacheTtl: 3600, cacheEverything: true } : undefined,
            });
            if (r.ok) {
                
                const ct = r.headers.get("content-type") || "";
                if (isRoot && /text\/html/i.test(ct)) {
                    try {
                        const body = await Promise.race([r.text(), new Promise((_, rej) => setTimeout(() => rej(new Error("decoy body timeout")), 4000))]);
                        if (typeof body === "string" && body.length > 0) {
                            if (body.length < 400000) { try { await edgeCachePutText("decoy_root_v1", JSON.stringify({ t: ct, b: body }), 1800); } catch (e) {} }
                            return new Response(request.method === "HEAD" ? null : body, { status: 200, headers: { "Content-Type": ct, "Cache-Control": "no-store" } });
                        }
                    } catch (e) { hardFails++; try { hawkLogErr("maintenance-decoy", e); } catch (x) {} continue; }
                    continue;
                }
                return r;
            }
            try { if (r.body) await r.body.cancel(); } catch (e) {}
        } catch (e) {
            hardFails++;
            if (!isRoot) return new Response("Not Found", { status: 404, headers: { "Content-Type": "text/plain; charset=utf-8", "Cache-Control": "no-store" } }); 
            try { hawkLogErr("maintenance-decoy", e); } catch (x) {}
            if (/Too many subrequests/i.test(String((e && e.message) || e))) { _decoyDownUntil = Date.now() + 30000; break; }
        }
    }
    if (hardFails > 0 && hardFails >= targets.length) _decoyDownUntil = Date.now() + 60000;
    return decoyFallback();
}



function migrateSlaveNodesToLinkedPanels(config) {
    let modified = false;
    if (config && config.slaveNodes && config.slaveNodes.trim().length > 0) {
        if (!config.linkedPanels) config.linkedPanels = [];
        let nodes = config.slaveNodes
            .split(/[\r\n,;]+/)
            .map((s) => s.trim())
            .filter(Boolean);
        let syncKey = config.syncApiKey || "";
        nodes.forEach((node) => {
            let cleanNode = node.replace(/^[a-zA-Z]+:\/\//, "").split("/")[0].split("@").pop().split(":")[0].toLowerCase();
            let exists = config.linkedPanels.some((p) => {
                if (!p || !p.url) return false;
                let cleanUrl = p.url.replace(/^[a-zA-Z]+:\/\//, "").split("/")[0].split("@").pop().split(":")[0].toLowerCase();
                return cleanUrl === cleanNode;
            });
            if (!exists) {
                config.linkedPanels.push({ url: node, apiKey: syncKey });
                modified = true;
            }
        });
        config.slaveNodes = "";
        modified = true;
    }
    return modified;
}











const D1_LOAD_TIMEOUT_MS = 5000;
function d1GetWithTimeout(env, key) {
    return Promise.race([
        d1Get(env, key),
        new Promise((_, reject) =>
            setTimeout(() => reject(new Error("d1 load timeout")), D1_LOAD_TIMEOUT_MS),
        ),
    ]).catch(() => null);
}
function loadUsageCountersWithTimeout(env) {
    return Promise.race([
        loadUsageCountersFromD1(env),
        new Promise((_, reject) =>
            setTimeout(() => reject(new Error("d1 usage load timeout")), D1_LOAD_TIMEOUT_MS),
        ),
    ]).catch(() => ({ users: {} }));
}
















async function pruneStaleD1Rows(env) {
    if (!env.IOT_DB || Math.random() > 1 / 300) return;
    const staleBefore = Date.now() - 14 * 24 * 60 * 60 * 1000;
    const tables = [
        "relay_speed",
        "direct_ip_history",
        "direct_domain_stats",
        "asn_domain_stats",
        "asn_relay_stats",
        "ip_geo_cache",
        "asn_cleanip_stats",
    ];
    for (const table of tables) {
        try {
            await env.IOT_DB.prepare(
                `DELETE FROM ${table} WHERE updated_at < ?`,
            )
                .bind(staleBefore)
                .run();
        } catch (e) {}
    }
}











let _bgConfigRefreshStartedAt = 0;
function refreshConfigInBackground(env, ctx) {
    const now = Date.now();
    const due =
        now - sysConfigCacheTime > CACHE_TTL_CONFIG ||
        now - sysUsageCacheTime > CACHE_TTL_USAGE ||
        now - backupIpCacheTime > CACHE_TTL_BACKUP_IP;
    if (!due) return;
    if (_bgConfigRefreshStartedAt && now - _bgConfigRefreshStartedAt < 10000) return;
    _bgConfigRefreshStartedAt = now;
    const p = loadSysConfig(env, ctx)
        .catch(() => {})
        .finally(() => {
            _bgConfigRefreshStartedAt = 0;
        });
    
    if (ctx && typeof ctx.waitUntil === "function") ctx.waitUntil(p);
}

async function loadSysConfig(env, ctx = null) {
    const now = Date.now();

    if (env.IOT_DB) {
        if (now - sysConfigCacheTime > CACHE_TTL_CONFIG) {
            try {
                const repoResult = await HawkState.repositories.getConfig();
                if (repoResult && repoResult.error) throw new Error(repoResult.error);
                const stored = repoResult && repoResult.value ? JSON.stringify(repoResult.value) : null;
                sysConfig = {
                    ...SYSTEM_DEFAULTS,
                    ...(stored ? JSON.parse(stored) : null),
                };
                normalizeMuxConfig(sysConfig);
                configRevision = sysConfig.__hawkConfigRevision || "legacy";
                
                
                
                sysConfigCacheTime = Date.now();
                sysConfigEverLoadedSuccessfully = true;
                
                
            } catch (e) {
                hawkRepoNote("read", "last-known-good", e);
                
                
                
                
                
                
                
                
                if (!sysConfigEverLoadedSuccessfully) {
                    sysConfig = { ...SYSTEM_DEFAULTS };
                }
                sysConfigCacheTime = Date.now() - CACHE_TTL_CONFIG + 2000;
            }
        }
        if (now - sysUsageCacheTime > CACHE_TTL_USAGE) {
            
            
            
            
            try {
                const loaded = await loadUsageCountersWithTimeout(env);
                sysUsageCache = loaded;
                sysUsageCacheTime = Date.now();
            } catch (e) {
                sysUsageCache = { users: {} };
                sysUsageCacheTime = Date.now();
            }
        }
    }

    if (now - backupIpCacheTime > CACHE_TTL_BACKUP_IP) {
        
        
        
        
        try {
            const val = env.IOT_DB
                ? await Promise.race([
                      d1GetStrict(env, "backup_ip"),
                      new Promise((_, reject) =>
                          setTimeout(() => reject(new Error("d1 backup_ip timeout")), D1_LOAD_TIMEOUT_MS),
                      ),
                  ])
                : null;
            backupIpCache = val;
            backupIpCacheTime = Date.now();
        } catch (e) {
            backupIpCacheTime = Date.now() - CACHE_TTL_BACKUP_IP + 5000;
        }
    }
    sysConfig.customRelay = backupIpCache ?? env.RELAY_IP ?? "";

    
    
    
    if (env.IOT_DB && Date.now() - relaySpeedCacheTime > RELAY_SPEED_CACHE_TTL) {
        try {
            relaySpeedStats = await loadMapViaEdgeCache(
                "kv:relay_speed",
                600,
                () => loadRelaySpeedsFromD1(env),
            );
            relaySpeedCacheTime = Date.now();
        } catch (e) {
            relaySpeedCacheTime = Date.now();
        }
    }

    
    
    if (env.IOT_DB && Date.now() - directIpHistoryCacheTime > DIRECT_IP_CACHE_TTL) {
        try {
            const loaded = await loadMapViaEdgeCache(
                "kv:direct_ip_history",
                600,
                () => loadDirectIpHistoryFromD1(env),
            );
            
            
            
            for (const [domain, entry] of loaded) {
                const existing = directIpHistory.get(domain);
                if (!existing || entry.lastGood > existing.lastGood) {
                    directIpHistory.set(domain, entry);
                }
            }
            directIpHistoryCacheTime = Date.now();
        } catch (e) {
            directIpHistoryCacheTime = Date.now();
        }
    }

    
    
    if (
        env.IOT_DB &&
        Date.now() - directDomainStatsCacheTime > DIRECT_DOMAIN_STATS_CACHE_TTL
    ) {
        try {
            directDomainStats = await loadMapViaEdgeCache(
                "kv:direct_domain_stats",
                600,
                () => loadDirectDomainStatsFromD1(env),
            );
            directDomainStatsCacheTime = Date.now();
        } catch (e) {
            directDomainStatsCacheTime = Date.now();
        }
    }

    
    
    if (
        env.IOT_DB &&
        Date.now() - asnDomainStatsCacheTime > ASN_DOMAIN_STATS_CACHE_TTL
    ) {
        try {
            asnDomainStats = await loadMapViaEdgeCache(
                "kv:asn_domain_stats",
                600,
                () => loadAsnDomainStatsFromD1(env),
            );
            asnDomainStatsCacheTime = Date.now();
        } catch (e) {
            asnDomainStatsCacheTime = Date.now();
        }
    }

    
    if (
        env.IOT_DB &&
        Date.now() - asnRelayStatsCacheTime > ASN_RELAY_STATS_CACHE_TTL
    ) {
        try {
            asnRelayStats = await loadMapViaEdgeCache(
                "kv:asn_relay_stats",
                600,
                () => loadAsnRelayStatsFromD1(env),
            );
            asnRelayStatsCacheTime = Date.now();
        } catch (e) {
            asnRelayStatsCacheTime = Date.now();
        }
    }
    
    
    try { await rhSync(env); } catch (e) { hawkLogErr("loadSysConfig", e); }
}

async function fetchCloudflareUsage(accountId, apiToken) {
    if (!accountId || !apiToken) return null;
    try {
        const d = new Date();
        const currentDate = d.toISOString().split("T")[0] + "T00:00:00Z";

        const query = `query GetDailyUsage($accountId: String!, $start: ISO8601DateTime!) { viewer { accounts(filter: {accountTag: $accountId}) { workersInvocationsAdaptive(limit: 1, filter: { datetime_geq: $start }) { sum { requests } } } } }`;
        const variables = { accountId: accountId, start: currentDate };

        const res = await fetch(
            "https://api.cloudflare.com/client/v4/graphql",
            {
                method: "POST",
                headers: {
                    Authorization: `Bearer ${apiToken}`,
                    "Content-Type": "application/json",
                },
                body: JSON.stringify({ query, variables }),
            },
        );

        const json = await res.json();
        const reqs =
            json?.data?.viewer?.accounts?.[0]?.workersInvocationsAdaptive?.[0]
                ?.sum?.requests;
        return typeof reqs === "number" ? reqs : null;
    } catch (e) {
        return null;
    }
}

