const IR_ASN_NAMES = {
    "197207": "همراه اول", "44244": "ایرانسل", "57218": "رایتل",
    "58224": "مخابرات", "31549": "شاتل", "16322": "پارس‌آنلاین",
    "43754": "آسیاتک", "50810": "مبین‌نت", "49100": "پیشگامان",
};
const _userNetSeen = new Map();
const _userShareAlertAt = new Map();
function _tgEsc(v) {
    return String(v == null ? "" : v).replace(/([_*`\[])/g, "\\$1");
}
function noteUserNetwork(env, ctx, profile, asn, asOrg) {
    try {
        if (!env || !env.IOT_DB || !profile || !asn || !sysConfig.tgToken) return;
        const uid = String(profile.id).replace(/-/g, "").toLowerCase();
        const key = `${uid}|${asn}`;
        const now = Date.now();
        const seen = _userNetSeen.get(key);
        if (seen && now - seen < 12 * 3600 * 1000) return;
        _userNetSeen.set(key, now);
        if (_userNetSeen.size > 20000) _userNetSeen.clear();
        const withTimeout = (p) => Promise.race([p, new Promise((_, r) => setTimeout(() => r(new Error("d1 timeout")), 4000))]);
        const p = (async () => {
            await d1Init(env);
            const row = await withTimeout(
                env.IOT_DB.prepare(
                    `INSERT INTO user_asn_seen (user_id, asn, first_seen, last_seen) VALUES (?1, ?2, ?3, ?3)
                     ON CONFLICT(user_id, asn) DO UPDATE SET last_seen = ?3
                     RETURNING first_seen`,
                ).bind(uid, String(asn), now).first(),
            );
            const counts = await withTimeout(
                env.IOT_DB.prepare(
                    "SELECT COUNT(*) AS total, SUM(CASE WHEN last_seen > ?2 THEN 1 ELSE 0 END) AS recent FROM user_asn_seen WHERE user_id = ?1",
                ).bind(uid, now - 24 * 3600 * 1000).first(),
            );
            const net = IR_ASN_NAMES[String(asn)] || asOrg || "";
            const who = _tgEsc(profile.name || "Default");
            if (row && row.first_seen === now && counts && counts.total > 1) {
                await sendAdminAlert(`🌐 *${who}* از یه شبکه‌ی جدید وصل شد\nASN ${asn} ${_tgEsc(net)}`);
            }
            if (counts && counts.recent >= 4) {
                const last = _userShareAlertAt.get(uid) || 0;
                if (now - last > 6 * 3600 * 1000) {
                    _userShareAlertAt.set(uid, now);
                    await sendAdminAlert(`⚠️ *${who}* توی ۲۴ ساعت از ${counts.recent} شبکه‌ی مختلف وصل شده. شاید اکانت رو به اشتراک گذاشته.`);
                }
            }
        })().catch(() => {});
        if (ctx && typeof ctx.waitUntil === "function") ctx.waitUntil(p);
    } catch (e) {}
}



function decodeEarlyDataHeader(value) {
    if (!value || value.length < 24 || value.length > 8192) return null;
    try {
        let b64 = value.trim().replace(/-/g, "+").replace(/_/g, "/");
        while (b64.length % 4) b64 += "=";
        const bin = atob(b64);
        if (bin.length < 18) return null;
        const out = new Uint8Array(bin.length);
        for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
        return out.buffer;
    } catch (e) {
        return null;
    }
}

function decodePathPayload(pathname) {
    try {
        let seg = String(pathname || "").slice(1);
        if (!seg || seg.length > 2048) return null;
        if (seg.indexOf("%") !== -1) seg = decodeURIComponent(seg);
        const o = JSON.parse(atob(seg));
        return o && typeof o === "object" ? o : null;
    } catch (e) {
        return null;
    }
}




















