    const RECONNECT_BACKOFF_BASE_MS = 250;
    const RECONNECT_BACKOFF_MAX_MS = 8000;
    function reconnectBackoffDelay() {
        if (!sysConfig || sysConfig.reconnectBackoff === false) return 0;
        const exp = Math.min(5, reconnectFailures);
        const raw = Math.min(RECONNECT_BACKOFF_MAX_MS, RECONNECT_BACKOFF_BASE_MS * (2 ** exp));
        return Math.round(raw * (0.75 + Math.random() * 0.5));
    }
    async function waitReconnectBackoff() {
        const delay = Math.max(0, nextReconnectAt - Date.now());
        if (delay) await new Promise((resolve) => setTimeout(resolve, delay));
    }
    function markReconnectSuccess() {
        reconnectFailures = 0;
        nextReconnectAt = 0;
    }
    function markReconnectFailure() {
        reconnectFailures = Math.min(8, reconnectFailures + 1);
        nextReconnectAt = Date.now() + reconnectBackoffDelay();
    }
    function relayFamily(host) {
        if (isIPv6Literal(host)) return 6;
        if (isIPv4Literal(host)) return 4;
        return 0;
    }
    function orderFamilyFallback(entries) {
        if (!sysConfig || sysConfig.familyFallback === false || entries.length < 2) return entries;
        const v4 = entries.filter((x) => relayFamily(getRelayHost(x)) === 4);
        const v6 = entries.filter((x) => relayFamily(getRelayHost(x)) === 6);
        const other = entries.filter((x) => ![4, 6].includes(relayFamily(getRelayHost(x))));
        if (!v4.length || !v6.length) return entries;
        const out = [];
        const first = v4.length >= v6.length ? v4 : v6;
        const second = first === v4 ? v6 : v4;
        const n = Math.max(first.length, second.length);
        for (let i = 0; i < n; i++) { if (first[i]) out.push(first[i]); if (second[i]) out.push(second[i]); }
        return out.concat(other);
    }

    async function connectFreshRelayCandidate(excludeIps) {
        const profile = cachedActiveProfile;
        let pips = [];
        if (profile && profile.\u0070roxyIp) pips = getRelayEntries(profile.\u0070roxyIp);
        if (pips.length === 0 && sysConfig.backupRelay)
            pips = getRelayEntries(sysConfig.backupRelay);
        if (pips.length === 0 && sysConfig.customRelay)
            pips = getRelayEntries(sysConfig.customRelay);
        if (profile && profile.cleanIp)
            pips = pips.concat(get\u0050roxyIpsArray(profile.cleanIp));
        pips = [...new Set(pips)];
        if (pips.length === 0) throw new Error("no relay candidates configured");
        const now = Date.now();
        const healthy = pips.filter((p) => {
            const ip = getRelayHost(p);
            const until = recentlyFailedRelays.get(ip);
            return !until || until < now;
        });
        const pool = sampleArray(healthy.length > 0 ? healthy : pips, 30);
        const speedValues = Array.from(relaySpeedStats.values());
        const neutralSpeed =
            speedValues.length > 0
                ? speedValues.reduce((a, b) => a + b, 0) / speedValues.length
                : 0;
        pool.sort((a, b) => {
            const ipA = getRelayHost(a);
            const ipB = getRelayHost(b);
            const speedA = asnAdjustedRelayScore(
                relaySpeedStats.has(ipA) ? relaySpeedStats.get(ipA) : neutralSpeed,
                ipA,
                clientAsn,
            );
            const speedB = asnAdjustedRelayScore(
                relaySpeedStats.has(ipB) ? relaySpeedStats.get(ipB) : neutralSpeed,
                ipB,
                clientAsn,
            );
            return speedB - speedA;
        });
        const familyOrdered = orderFamilyFallback(pool);
        const filtered = excludeIps
            ? familyOrdered.filter((p) => !excludeIps.has(getRelayHost(p)))
            : familyOrdered;
        const chosen = filtered.length > 0 ? filtered[0] : pool[0];
        if (!chosen) throw new Error("no relay candidates available");
        const endpoint = parseRelayEndpoint(chosen, cachedTargetPort);
        if (!endpoint?.host) throw new Error("invalid relay endpoint");
        const ip = endpoint.host;
        const port = hawkRelayDialPort(endpoint.port, cachedTargetPort);
        const sock = await connectWithTimeout(ip, port, true);
        return { sock, ip };
    }

    
    
    
    
    
    
