function parseSniSeedText(text) {
    const out = new Set();
    for (let line of String(text || "").split(/\r?\n/)) {
        line = line.trim(); if (!line || line[0] === "#") continue;
        const rule = line.match(/^(?:domain-suffix|host-suffix)\s*,\s*([^,\s]+)/i);
        if (rule) line = rule[1];
        else if (line.includes(",")) { const q = line.split(","); line = q[q.length - 1].trim(); }
        line = line.split(/\s+/)[0].replace(/^(domain|full):/i, "").replace(/@.*$/, "").toLowerCase();
        if (/^(include|regexp|keyword):/.test(line)) continue;
        if (/^(?=.{3,253}$)[a-z0-9](?:[a-z0-9-]*[a-z0-9])?(?:\.[a-z0-9](?:[a-z0-9-]*[a-z0-9])?)+$/.test(line)) out.add(line);
        if (out.size >= SNI_SEED_MAX) break;
    }
    return [...out];
}
async function readCapped(resp, maxBytes) {
    const r = resp.body.getReader(), dec = new TextDecoder(); let txt = "", n = 0;
    try { while (n < maxBytes) { const z = await r.read(); if (z.done) break; const chunk = z.value.byteLength > maxBytes - n ? z.value.subarray(0, maxBytes - n) : z.value; n += chunk.byteLength; txt += dec.decode(chunk, { stream: true }); } }
    finally { try { await r.cancel(); } catch (e) {} }
    const cut = txt.lastIndexOf("\n"); return n >= maxBytes && cut > 0 ? txt.slice(0, cut) : txt;
}
function sniSeedCandidates() { return Array.isArray(sniSeedState.candidates) ? sniSeedState.candidates : []; }
async function loadSniSeedState() { if (Date.now() - sniSeedLoadedAt < 180000) return; sniSeedLoadedAt = Date.now(); try { const t = await edgeCacheGetText(SNI_SEED_EDGE); if (t) { const j = JSON.parse(t); if (Array.isArray(j.candidates)) sniSeedState = { ...sniSeedState, ...j }; } } catch (e) {} }
async function fetchSniSeeds(env, ctx, force = false) {
    await loadSniSeedState();
    if (sniSeedFetchP) return sniSeedFetchP;
    if (!force && sniSeedState.candidates.length && Date.now() - (sniSeedState.fetchedAt || 0) < 86400000) return sniSeedState;
    sniSeedFetchP = (async () => {
        const all = [], errors = [], sources = [];
        for (const src of SNI_SEED_SOURCES) {
            try {
                const r = await fetch(src.url, { signal: AbortSignal.timeout(6000), cf: { cacheTtl: 86400, cacheEverything: true } });
                if (!r.ok || !r.body) throw new Error("HTTP " + r.status);
                const list = parseSniSeedText(await readCapped(r, src.maxBytes));
                if (!list.length) throw new Error("empty or unsupported format");
                all.push(...list); sources.push({ url: src.url, format: src.format, count: list.length });
            } catch (e) { errors.push({ url: src.url, error: String(e && e.message || e).slice(0, 120) }); }
        }
        const merged = [...new Set(all)].slice(0, SNI_SEED_MAX);
        
        if (merged.length) sniSeedState = { candidates: merged, fetchedAt: Date.now(), sources, errors };
        else sniSeedState = { ...sniSeedState, errors, lastErrorAt: Date.now() };
        await edgeCachePutText(SNI_SEED_EDGE, JSON.stringify(sniSeedState), 172800, null);
        return sniSeedState;
    })().catch(e => ({ ...sniSeedState, errors: [{ error: String(e) }] })).finally(() => { sniSeedFetchP = null; });
    return sniSeedFetchP;
}
function sniSeedReport() { return { success: true, version: CURRENT_VERSION, sources: SNI_SEED_SOURCES.map(x => x.url), candidates: sniSeedCandidates().length, fetchedAt: sniSeedState.fetchedAt || 0, perSource: sniSeedState.sources || [], errors: sniSeedState.errors || [], sample: sniSeedCandidates().slice(0, 30) }; }
function sniInfo(v) { const e=sniPoolState.h&&sniPoolState.h[v]; return e?{ok:e[0]===1,ms:e[1]||0,fails:e[2]||0,lastOk:e[3]||0,firstFail:e[4]||0,lastCheck:e[5]||0,mode:e[6]||""}:null; }
function sniClass(v) { const e=sniInfo(v); if(!e) return "u"; if(e.fails>=SNI_FAIL_QUARANTINE) return "d"; return e.ok?"a":"s"; }
