function sniActiveFor(asn="default") { const op=sniPoolState.byOperator&&sniPoolState.byOperator[String(asn)]; const a=op&&Array.isArray(op.active)?op.active:[]; if(a.length)return a.filter(x=>!sniClientBlocked(asn,x)); return sniCandidates().filter(x=>sniClass(x)!=="d"&&!sniClientBlocked(asn,x)).sort((a,b)=>(sniInfo(a)?.ms||99999)-(sniInfo(b)?.ms||99999)).slice(0,warmPoolSize()); }
