        const q = await env.IOT_DB.prepare("SELECT asn, COUNT(*) AS n, SUM(ok) AS ok, SUM(bad) AS bad, SUM(CASE WHEN last_ok > ?1 THEN 1 ELSE 0 END) AS alive24, MAX(last_ok) AS last_ok, MAX(updated_at) AS upd FROM asn_cleanip_stats GROUP BY asn ORDER BY upd DESC LIMIT 30").bind(now - 86400000).all();
