const HAWK_DOMAIN_RE = /^(?=.{3,253}$)[a-z0-9](?:[a-z0-9-]*[a-z0-9])?(?:\.[a-z0-9](?:[a-z0-9-]*[a-z0-9])?)+$/;
function clientScanKindOk(kind, v) {
    if (kind === "ipv4") return isIPv4Literal(v) && isCloudflareIp(v);
    if (kind === "ipv6") return isIPv6Literal(v) && isCloudflareIp(v);
    return kind === "sni" && HAWK_DOMAIN_RE.test(v);
}
function clientScanOp(asn) { const by = clientScanState.byOperator || (clientScanState.byOperator = {}); const k = String(asn || "default"); return by[k] || (by[k] = {}); }
