const DSY_OPS = ["mci", "tci", "irancell", "rightel", "fixed", "default"];
const DSY_OPNAME = { mci: "همراه اول", tci: "مخابرات", irancell: "ایرانسل", rightel: "رایتل", fixed: "اینترنت ثابت", default: "بقیه" };
