function getConfigName(
    type,
    profileName,
    port,
    hostName,
    ip,
    \u0070roxyIp = null,
    configIndex = 0,
    ipName = "",
    isDirect = false
) {
    let prefix = sysConfig.namePrefix || "Core";
    let strategy = sysConfig.nameStrategy || "default";
    let cleanName = profileName === "Default" ? "" : `-${profileName}`;
    let typeLab = type === "alpha" ? "V" : "T";

    if (strategy.includes("{") && strategy.includes("}")) {
        let lookupIp = \u0070roxyIp || ip;
        let geoInfo = getGeoInfo(lookupIp);
        let protoLab = type === "alpha" ? "\x56LESS" : "\x54rojan";
        let now = new Date();
        let dateStr =
            now.getFullYear() +
            "-" +
            String(now.getMonth() + 1).padStart(2, "0") +
            "-" +
            String(now.getDate()).padStart(2, "0");
        let workerName =
            sysConfig.cfWorkerName || sysConfig.name || hostName || "";
        let flagToUse = isDirect ? "☁️" : geoInfo.flag;
        let resName = strategy
            .replace(/{FLAG}/g, flagToUse)
            .replace(/{COUNTRY}/g, geoInfo.country)
            .replace(/{CITY}/g, geoInfo.city)
            .replace(/{ISP}/g, geoInfo.isp)
            .replace(/{PROTOCOL}/g, protoLab)
            .replace(/{USER}/g, profileName)
            .replace(/{PORT}/g, port)
            .replace(/{PREFIX}/g, prefix)
            .replace(/{IP}/g, ip || "")
            .replace(/{IP_NAME}/g, ipName || "")
            .replace(/{HOST}/g, hostName || "")
            .replace(/{DATE}/g, dateStr)
            .replace(/{INDEX}/g, String(configIndex))
            .replace(/{WORKER}/g, workerName);
        return resName;
    }

    if (strategy === "type-user-port") {
        return `${type === "alpha" ? "vl" + "ess" : "tro" + "jan"}-${profileName}-${port}`;
    } else if (strategy === "user-port") {
        return `${profileName}-${port}`;
    } else if (strategy === "host-port-user") {
        return `${hostName}-${port}${cleanName}`;
    } else if (strategy === "prefix-user-port") {
        return `${prefix}${cleanName}-${port}`;
    } else if (strategy === "ip") {
        return ip || "unknown";
    } else {
        
        return `${typeLab}-Core-${port}${cleanName}`;
    }
}












function isIPv4Literal(value) {
    const p = String(value || "").trim().split(".");
    return p.length === 4 && p.every(x => /^\d{1,3}$/.test(x) && Number(x) >= 0 && Number(x) <= 255);
}





const CF_V4_CIDRS = ["173.245.48.0/20", "103.21.244.0/22", "103.22.200.0/22", "103.31.4.0/22", "141.101.64.0/18", "108.162.192.0/18", "190.93.240.0/20", "188.114.96.0/20", "197.234.240.0/22", "198.41.128.0/17", "162.158.0.0/15", "104.16.0.0/13", "104.24.0.0/14", "172.64.0.0/13", "131.0.72.0/22"];
const CF_V4_RANGES = CF_V4_CIDRS.map((c) => {
    const [ip, bits] = c.split("/");
    const n = ip.split(".").reduce((a, o) => a * 256 + Number(o), 0);
    const size = Math.pow(2, 32 - Number(bits));
    return [n, n + size - 1];
});
function isCloudflareIp(addr) {
    const v = String(addr || "").trim().replace(/^\[|\]$/g, "").toLowerCase();
    if (isIPv4Literal(v)) {
        const n = v.split(".").reduce((a, o) => a * 256 + Number(o), 0);
        return CF_V4_RANGES.some(([lo, hi]) => n >= lo && n <= hi);
    }
    if (isIPv6Literal(v)) {
        const first = v.split(":");
        const h0 = parseInt(first[0] || "0", 16), h1 = parseInt(first[1] || "0", 16);
        if ((h0 === 0x2400 && h1 === 0xcb00) || (h0 === 0x2606 && h1 === 0x4700) || (h0 === 0x2803 && h1 === 0xf800) || (h0 === 0x2405 && (h1 === 0xb500 || h1 === 0x8100)) || (h0 === 0x2c0f && h1 === 0xf248)) return true;
        if (h0 === 0x2a06 && h1 >= 0x98c0 && h1 <= 0x98c7) return true;
        return false;
    }
    return false;
}
function isNonCfIpTarget(addr) {
    if (_hawkOff.has("noncf")) return false;
    return (isIPv4Literal(addr) || isIPv6Literal(addr)) && !isCloudflareIp(addr);
}
function isIPv6Literal(ip) {
    const v = String(ip || "").trim().replace(/^\[|\]$/g, "");
    return (
        (v.includes("::") || (v.match(/:/g) || []).length >= 2) &&
        /^[0-9A-Fa-f:.]+$/.test(v)
    );
}
function formatHostForUri(ip) {
    
    return isIPv6Literal(ip) ? `[${String(ip).trim().replace(/^\[|\]$/g, "")}]` : ip;
}

function formatHostForData(ip) { return String(ip || "").trim().replace(/^\[|\]$/g, ""); }









const HAWK_RELAY_PLAIN_PORTS = new Set([80, 8080, 8880, 2052, 2082, 2086, 2095]);
function hawkRelayDialPort(relayPort, targetPort) { const t = Number(targetPort) || 443; if (HAWK_RELAY_PLAIN_PORTS.has(t)) return t; return Number(relayPort) || t; }
function parseRelayEndpoint(value, fallbackPort = null) {
    let raw = String(value || "").trim();
    if (!raw) return null;
    raw = raw.split("#")[0].split("@").pop().trim();
    if (!raw) return null;
    if (raw.startsWith("[")) {
        const close = raw.indexOf("]");
        if (close > 0) {
            const host = raw.slice(1, close);
            const rest = raw.slice(close + 1);
            const port =
                rest.startsWith(":") && /^\d+$/.test(rest.slice(1))
                    ? Number(rest.slice(1))
                    : fallbackPort;
            return { host, port };
        }
    }
    if (isIPv4Literal(raw)) return { host: raw, port: fallbackPort };
    if (isIPv6Literal(raw)) return { host: raw, port: fallbackPort };
    const lastColon = raw.lastIndexOf(":");
    if (lastColon > 0 && /^\d+$/.test(raw.slice(lastColon + 1))) {
        return {
            host: raw.slice(0, lastColon),
            port: Number(raw.slice(lastColon + 1)),
        };
    }
    return { host: raw, port: fallbackPort };
}
function getRelayHost(value) {
    return parseRelayEndpoint(value)?.host || "";
}


function withCleanIpTag(extBase, reqPath, server) {
    
    
    
    const m = /(?:^|&)fp=([a-z0-9]+)/.exec(extBase);
    const fx = m && ADAPTIVE_FPS.includes(m[1]) ? "&fx=" + m[1] : "";
    return extBase.replace(
        "&path=" + reqPath,
        "&path=" + encodeURIComponent(decodeURI(reqPath) + "?ci=" + cleanIpKey(server) + fx + (activeBuildMethod ? "&mt=" + activeBuildMethod : "") + (activeCanary ? "&cn=1" : "") + (activeFrontAsn ? "&oa=" + activeFrontAsn : "")),
    );
}





function splitMaxCfg(maxCfg, hostCount) {
    if (!maxCfg || !(hostCount > 1)) return maxCfg;
    return Math.max(1, Math.floor(maxCfg / hostCount));
}

